EK.put("g2", {
  core: {
    // ===== 動詞 =====
    "abandon": { hint: "それまで続けてきたことを、途中で手放してしまう場面", core: "持っていた人・もの・計画を『手放して、もう戻らない』。人を手放す→見捨てる、計画を手放す→断念する。", tip: "abandoned house（だれも住まなくなった家）のように、人が手放した場所にも使う。", pic: "🚮", scene: "雨の中、こわれた自転車が道ばたに置き去りにされ、持ち主はもう二度と取りに来ない。", flow: ["手放して戻らない", "人・動物を見捨てる", "計画・望みを断念する"], pair: "give up は「あきらめる」全般、abandon は「手放して置き去りにする」強さがある。" },
    "accompany": { hint: "小さな子が出かけるとき、大人がとなりについて歩く", core: "だれかの『そばについて、いっしょに行く』。子どもに大人がつく。歌に楽器がつく（伴奏）のも同じ。", tip: "ac（～に）＋company（仲間）＝仲間としてつく。companion（仲間）も同じ仲間。", scene: "コンサートで、歌手の声にピアノの音がぴったりついて流れていく。", flow: ["そばについて行く", "人に同行する", "歌に伴奏がつく"], parts: [["ac", "～に（ad）"], ["company", "仲間"]], fam: ["company（仲間・会社）", "companion（仲間）"], pair: "accompany は人に「ついて行く」、follow は「あとを追う」。" },
    "accomplish": { hint: "長い時間をかけた大仕事を、とうとう最後までやり切る", core: "時間をかけて『最後まで仕上げる』。1000本の木を植えるという目標をやり切った。", tip: "ac（～へ）＋complish（完全にする）。complete（完全な）と同じ語源。", pic: "🏁", scene: "汗だくのチームが、1000本目の苗木を植え終え、みんなで大きく手をたたく。", flow: ["最後まで仕上げる", "目標・仕事を成し遂げる"], parts: [["ac", "～へ（ad）"], ["compl", "満たす"], ["ish", "～する"]], fam: ["complete（完全な・仕上げる）"], pair: "achieve は「目標に届く」、accomplish は「やるべきことをやり切る」感じ。" },
    "acquire": { hint: "時間や努力をかけて、少しずつ自分のものにしていく", core: "外にあるものを『求めて、自分のものにする』。言葉や技術を身につける、会社や物を手に入れる。", tip: "ac（～へ）＋quire（求める）。question（質問＝答えを求める）と同じ仲間。", scene: "アメリカに引っこした幼い妹が、半年で英語をぺらぺら話すようになっていた。", flow: ["求めて自分のものに", "言葉・技術を習得する", "物・会社を得る"], parts: [["ac", "～へ（ad）"], ["quire", "求める"]], fam: ["require（必要とする）", "inquire（たずねる）"], pair: "get は何でも「手に入れる」、acquire は努力や時間をかけて身につける感じ。" },
    "adapt": { hint: "電源アダプターは、形のちがうものどうしを合わせる道具", core: "まわりに『合うように自分を変えていく』。新しい国の生活に自分を合わせる。adapt to ～の形。", tip: "ad（～に）＋apt（ぴったり合う）。アダプター（adapter）と同じ。", pic: "🦎", scene: "ブラジルから来た転校生が、最初は箸に苦戦したが、3か月後には給食を箸で上手に食べている。", flow: ["形を合わせる", "環境に適応する", "作品を作り変える"], parts: [["ad", "～に"], ["apt", "ぴったり合う"]], fam: ["adapter（アダプター）", "adaptation（適応・脚色）"], pair: "adapt は「合わせて変わる」、adopt は「採用する・養子にする」。つづりに注意。" },
    "adjust": { hint: "ちょうどよくなるように、少しずつ動かす", core: "『ちょうどよい位置にぴったり合わせる』。いすの高さ、時計、生活のリズムを少し動かしてぴったりにする。", tip: "just（ぴったり）に近づける、と覚えると便利。名詞は adjustment。", pic: "🎚️", scene: "背の低い子がいすの下のレバーを引き、机に合う高さまでいすを上げる。", flow: ["ぴったりに合わせる", "高さ・設定を調整する", "新生活に慣れる"], fam: ["adjustment（調整）"], pair: "adapt は「自分を変えて合わせる」、adjust は「少し動かしてちょうどよくする」。" },
    "admit": { hint: "もとの意味は、中に『入れる』", core: "中に『入れる』。人を中に入れる→入場を許す、いやな事実を心の中に受け入れる→（しぶしぶ）認める。", tip: "ad（～へ）＋mit（送る）＝中へ送り入れる。admission（入場）も同じ仲間。", scene: "先生に問いつめられた男子が、うつむいて『ぼくが窓を割りました』と小さく言う。", flow: ["中に入れる", "入場・入学を許す", "事実を（しぶしぶ）認める"], parts: [["ad", "～へ"], ["mit", "送る"]], fam: ["admission（入場・入学）", "submit（提出する）", "permit（許す）"], pair: "admit は「いやな事実をしぶしぶ認める」、deny は「否定する」で反対。" },
    "alter": { hint: "今とは『別の形』にするイメージ", core: "今の形を『別の形にする』。お客の声を聞いて計画の一部を作りかえる。服のサイズ直しにも使う。", tip: "ラテン語 alter（もう一方の）から。alternative（代わりのもの）と同じ仲間。", pic: "✂️👕", scene: "仕立て屋さんが、長すぎるズボンのすそをチョキンと切って、ぬい直している。", flow: ["別の形にする", "計画・服を変える"], fam: ["alternative（代わりの）", "alternate（交互の）"], pair: "change は何でも「変える」、alter は一部を手直しして形を変える。" },
    "analyze": { hint: "データを見て原因をさぐる『アナリスト』の仕事", core: "全体を『ばらばらにほどいて』一つずつ調べる。水を細かく調べて、病気の原因を見つける。", tip: "ana（ばらばらに）＋lyze（ほどく）。analyst（アナリスト）と同じ。", pic: "🔬", scene: "白衣の科学者が、試験管の水を何本にも分け、顕微鏡で一つずつのぞいていく。", flow: ["ばらばらにほどく", "細かく分析する"], parts: [["ana", "すっかり・上へ"], ["lyze", "ほどく"]], fam: ["analysis（分析）", "analyst（アナリスト）"], pair: "examine は「じっくり調べる」、analyze は「要素に分けて調べる」。" },
    "anticipate": { hint: "まだ起きていないことを、先に頭に思いうかべる", core: "起こる『前に先回りして考える』。こんなに人が来るとは、前もって思っていなかった。", tip: "anti（＝ante 前もって）＋cip（取る）＝先につかむ。", scene: "雨雲を見た店長が、まだ降り出す前に、店先にかさをずらりと並べておく。", flow: ["先回りして考える", "前もって予想する", "期待して待つ"], parts: [["anti", "前に（ante）"], ["cip", "取る"], ["ate", "～する"]], fam: ["participate（参加する）"], pair: "expect は「来ると思って待つ」、anticipate は「先回りして備える」感じもある。" },
    "appreciate": { hint: "price（値段）が中にかくれている", core: "もののねうちを『きちんとわかる』。助けのありがたさがわかる→感謝する、よさがわかる→評価する。", tip: "ap（～に）＋preci（値段）＝値打ちをつける。price と同じ語源。", scene: "重い段ボールを運び終えた友だちに、何度も頭を下げて『本当に助かった』と言う。", flow: ["値打ちがわかる", "ありがたさ→感謝する", "よさ→評価する・味わう"], parts: [["ap", "～に（ad）"], ["preci", "値段"], ["ate", "～する"]], fam: ["price（値段）", "precious（貴重な）"], pair: "thank は人に感謝、appreciate は「こと（help など）」を目的語にとる。" },
    "approve": { hint: "上の人が書類を読み、『これでよし』と言う", core: "『よいと見て OK を出す』。市議会が図書館の計画にゴーサインを出す。", tip: "ap（～に）＋prove（よいと確かめる）。名詞は approval。", scene: "市議会で、議長が書類にポンと判を押し、図書館の建設がいよいよ始まる。", flow: ["よいと認める", "計画を承認する", "approve of で賛成する"], parts: [["ap", "～に（ad）"], ["prove", "よいと示す"]], fam: ["approval（承認）", "prove（証明する）"], pair: "agree は「同じ意見になる」、approve は「上の立場から OK を出す」。" },
    "assess": { hint: "専門家が来て、どのくらいかを見きわめる", core: "じっくり見て『どのくらいか値ぶみする』。嵐のあと、家の被害がどれほどかを専門家が見る。", tip: "ラテン語 as（そばに）＋sess（座る）。裁判官のそばに座って額を決めた人から。", scene: "嵐の翌朝、保険会社の人がメモを片手に、こわれた屋根を一枚ずつ見て回る。", flow: ["見て値ぶみする", "被害・価値を査定する", "能力を評価する"], parts: [["as", "そばに（ad）"], ["sess", "座る"]], fam: ["assessment（評価・査定）"], pair: "evaluate は「価値を判断する」、assess は特に「量・程度を見きわめる」。" },
    "assume": { hint: "証拠もないのに、そうだと決めて話を進める", core: "確かめずに『そうだと受け取る』。月曜は休みだと思い込む。責任を引き受けるのも同じ『受け取る』。", tip: "as（～へ）＋sume（取る）。consume と同じ sume＝取る。", scene: "月曜日の朝、看板も見ずに『どうせ休みだ』と決めつけて、博物館の前を素通りする。", flow: ["確かめずに受け取る", "思い込む・仮定する", "責任を引き受ける"], parts: [["as", "～へ（ad）"], ["sume", "取る"]], fam: ["consume（消費する）", "resume（再開する）", "assumption（仮定）"], pair: "guess は「当てずっぽうに言う」、assume は「本当だと決めて話を進める」。" },
    "attach": { hint: "メールに写真やファイルをつけるときのボタン名", core: "『くっつける』。申しこみ用紙に写真をくっつける、メールにファイルをくっつける。", tip: "メールの『添付ファイル』は attachment。カタカナでアタッチメント。", pic: "📎", scene: "申込書の右上に、のりで顔写真をぺたりとはりつける。", flow: ["くっつける", "物を取り付ける", "メールにファイルを添付"], fam: ["attachment（添付ファイル）"], pair: "attach は「くっつける」、attack（攻撃する）とつづりが似ているので注意。" },
    "distribute": { hint: "たくさんのものを、一人ひとりにわたしていく場面", core: "『あちこちに分けて行きわたらせる』。マラソンのコースでランナーたちに水をわたす。", tip: "dis（ばらばらに）＋tribute（与える）。contribute（貢献する）と同じ仲間。", pic: "🥤🥤🥤", scene: "マラソンの給水所で、ボランティアが紙コップの水を走る人に次々と手わたす。", flow: ["分けて行きわたらせる", "物を配る", "富・利益を分配する"], parts: [["dis", "ばらばらに"], ["tribute", "与える"]], fam: ["contribute（貢献する）", "distribution（分配・流通）"], pair: "share は「みんなで分け合う」、distribute は「一人ひとりに配っていく」。" },
    "boost": { hint: "ロケットのブースター、ゲームのブースト", core: "下から『ぐっと押して勢いをつける』。お祭りで町の経済をぐんと上向きにする。", tip: "ブースターロケットが下から押して加速させる場面で覚える。", pic: "🚀", scene: "閉店寸前だった商店街に、お祭りの屋台が並び、どの店のレジも行列になる。", flow: ["下からぐっと押す", "経済・売上を押し上げる", "やる気・自信を高める"], pair: "increase は「量が増える」、boost は「外から力を加えて一気に上げる」。" },
    "calculate": { hint: "カリキュレーター（電卓）を使う作業", core: "数を『数え合わせて答えを出す』。旅行にいくら必要か、数字で出す。", tip: "ラテン語 calculus（小石）から。昔は小石を並べて数えた。calculator も同じ。", pic: "🧮", scene: "旅行のパンフレットを広げ、電卓で飛行機代とホテル代をたし合わせる。", flow: ["数え合わせる", "金額・量を計算する"], fam: ["calculator（電卓）", "calculation（計算）"], pair: "count は「1つずつ数える」、calculate は「数字を使って答えを出す」。" },
    "collapse": { hint: "建物や人が、支えをなくして一気にくずれる", core: "支えをなくして『一気にくずれ落ちる』。橋がくずれる、人がばったり倒れる、会社がつぶれる。", tip: "col（いっしょに）＋lapse（すべり落ちる）＝全部いっしょに落ちる。", pic: "🧱💥", scene: "嵐の夜、川にかかる古い木の橋が、バキッと音を立てて一気に水へくずれ落ちる。", flow: ["一気にくずれ落ちる", "建物が崩壊する", "人が倒れる・会社がつぶれる"], parts: [["col", "いっしょに"], ["lapse", "すべり落ちる"]], pair: "fall は「落ちる」全般、collapse は「支えを失ってぺしゃんこになる」。" },
    "combine": { hint: "コンビ（二人組）・コンビネーション", core: "2つ以上を『一つにまとめる』。和食の伝統とフランス料理の技を合体させる。", tip: "com（いっしょに）＋bine（2つずつ）。コンビ・コンビネーションと同じ。", scene: "フライパンの上で、しょうゆとバターが混ざり合い、新しい香りが立ちのぼる。", flow: ["一つにまとめる", "組み合わせる・結びつける"], parts: [["com", "いっしょに"], ["bine", "2つずつ"]], fam: ["combination（組み合わせ）"], pair: "mix は「まぜてわからなくする」、combine は「組み合わせて一つにする」。" },
    "commit": { hint: "警察のニュースで crime とセットでよく出る", core: "自分を『あることにゆだねて送り出す』。悪い行動に身をゆだねる→罪を犯す。全力をそそぐ（be committed）も同じ。", tip: "com（すっかり）＋mit（送る）。commit a crime の形で覚えよう。", scene: "防犯カメラに、夜の店に忍びこんでレジを開ける男の姿が映っていた。", flow: ["身をゆだねて送り出す", "罪・まちがいを犯す", "受け身で全力をそそぐ"], parts: [["com", "すっかり"], ["mit", "送る"]], fam: ["commitment（献身・約束）", "committee（委員会）"], pair: "commit は「罪を犯す」、violate は「規則・法をやぶる」。" },
    "compete": { hint: "コンペ（コンテスト）で一位をめざす", core: "同じものを『いっしょに求めて争う』。小さな店がネットの大きな店とお客をとり合う。", tip: "com（いっしょに）＋pete（求める）。competition（競争・コンペ）も同じ。", pic: "🥊", scene: "商店街の小さな八百屋の向かいに大型スーパーができ、お客の取り合いが始まる。", flow: ["いっしょに求めて争う", "競争する・張り合う"], parts: [["com", "いっしょに"], ["pete", "求める"]], fam: ["competition（競争）", "competitive（競争の）"], pair: "compete は「張り合う」、complete（完成させる）とつづりが似ている。" },
    "conduct": { hint: "コンダクター（指揮者・車掌）は人を導く", core: "『導いて進める』。実験や調査を先頭に立って進める→行う。音楽を導く人が指揮者。", tip: "con（いっしょに）＋duct（導く）。conductor（指揮者）と同じ。", pic: "🎼", scene: "白衣の研究者たちが、ノートを手に、ネズミに新しい薬を与える実験を進めている。", flow: ["導いて進める", "実験・調査を行う", "音楽を指揮する"], parts: [["con", "いっしょに"], ["duct", "導く"]], fam: ["conductor（指揮者）", "produce（生産する）"], pair: "do は何でも「する」、conduct は「調査・実験を計画的に進める」。" },
    "confirm": { hint: "firm（かたい・しっかりした）が入っている", core: "あいまいなものを『しっかり固める』。予約が本当にあるか、電話して固めておく。", tip: "con（すっかり）＋firm（かたい）＝しっかり固める。", scene: "出発前夜、ホテルに電話して『明日2名で予約していますよね』と念をおす。", flow: ["しっかり固める", "予約・事実を確認する"], parts: [["con", "すっかり"], ["firm", "かたい"]], fam: ["confirmation（確認）", "firm（かたい）"], pair: "check は「調べる」、confirm は「正しいと確かめて決める」。" },
    "consume": { hint: "古い冷蔵庫は電気をたくさん『食う』", core: "すっかり『取って使いきる』。古い冷蔵庫は電気をたくさん使う。食べる・飲むことにも使う。", tip: "con（すっかり）＋sume（取る）。consumer（消費者）はこの語＋er。", pic: "🍽️", scene: "真夏の夜、エアコンを3台つけっぱなしにした家の電気メーターがぐるぐる回る。", flow: ["すっかり使いきる", "電気・時間を消費する", "食べる・飲む"], parts: [["con", "すっかり"], ["sume", "取る"]], fam: ["consumer（消費者）", "consumption（消費）"], pair: "use は「使う」全般、consume は「使ってなくしてしまう」。" },
    "convince": { hint: "言葉で相手の心を『勝ち取る』イメージ", core: "相手を言葉で『負かして、そうだと思わせる』。親を説き伏せて、留学をみとめてもらう。", tip: "con（すっかり）＋vince（勝つ）。victory（勝利）と同じ仲間。", scene: "夕食のテーブルで、留学のパンフレットを広げ、両親が『わかった』とうなずくまで話す。", flow: ["言葉で相手を負かす", "納得させる", "be convinced で確信する"], parts: [["con", "すっかり"], ["vince", "勝つ"]], fam: ["victory（勝利）", "convincing（説得力のある）"], pair: "persuade は「説得して行動させる」、convince は「本当だと思わせる」。" },
    "cooperate": { hint: "生協（コープ）は人々が力を合わせる組織", core: "『いっしょに働く』。2つの国が手を組んで、海をよごれから守る。", tip: "co（いっしょに）＋operate（働く）。生協の『コープ』も co-op から。", pic: "🤝", scene: "2つの国の船が並び、両方の乗組員がいっしょに網を引いて海のごみを引き上げる。", flow: ["いっしょに働く", "協力する"], parts: [["co", "いっしょに"], ["operate", "働く"]], fam: ["cooperation（協力）", "co-op（生協）"], pair: "help は「手伝う」、cooperate は「対等に力を合わせる」。" },
    "decline": { hint: "ゆるやかな『下り坂』をイメージ", core: "『下へかたむく』。数が下へ→減っていく。申し出から体をそらす→（ていねいに）断る。", tip: "de（下へ）＋cline（かたむく）。incline（かたむける）と同じ仲間。", pic: "📉", scene: "村の学校の名簿が年ごとに短くなり、グラフの線がゆっくり右下へ下がっていく。", flow: ["下へかたむく", "数・力が減少する", "申し出を断る"], parts: [["de", "下へ"], ["cline", "かたむく"]], fam: ["incline（かたむける）"], pair: "refuse は「きっぱり断る」、decline は「ていねいに断る」。" },
    "define": { hint: "fin（終わり・境目）が中にある", core: "『境目をはっきり決める』。ここからここまでが『幸せ』だと線を引く→言葉の意味をはっきりさせる。", tip: "de（すっかり）＋fine（境目）。finish（終える）と同じ fin。", scene: "黒板に大きく円を書き、『ここからここまでが幸せ』と線で区切って見せる。", flow: ["境目をはっきり決める", "言葉の意味を定義する"], parts: [["de", "すっかり"], ["fine", "境目・終わり"]], fam: ["definition（定義）", "finish（終える）", "final（最後の）"], pair: "explain は「わかるように説明する」、define は「意味の範囲を決める」。" },
    "demonstrate": { hint: "お店でやって見せる『デモ』", core: "目の前で『やって見せる』。掃除機の使い方をお店で見せる。デモ行進は意見を見せること。", tip: "de（すっかり）＋monstrate（見せる）。デモンストレーション（デモ）と同じ。", scene: "家電売り場で、店員さんがこぼした粉を掃除機でスーッと吸いこんで見せる。", flow: ["目の前で見せる", "使い方を実演する", "証明する・示す"], parts: [["de", "すっかり"], ["monstr", "見せる"], ["ate", "～する"]], fam: ["demonstration（デモ・実演）"], pair: "show は「見せる」全般、demonstrate は「実際にやってはっきり示す」。" },
    "deny": { hint: "疑われたことに『No』と言う場面", core: "『それはちがう』と打ち消す。お金を受け取ったことを『していない』と言う。", tip: "deny that ～の形でよく出る。反対は admit（認める）。", pic: "🙅", scene: "記者にマイクを向けられた政治家が、首を横にふって『受け取っていません』と言う。", flow: ["『ちがう』と打ち消す", "事実を否定する", "要求を拒む"], fam: ["denial（否定）"], pair: "deny は「事実を否定する」、refuse は「要求を断る」。" },
    "deserve": { hint: "がんばった人が『それをもらって当然』の場面", core: "したことに見合って『それを受けるのにふさわしい』。1年がんばったから休みをもらって当然。悪いことにも使う。", tip: "You deserve it!（当然だよ、よかったね）の決まり文句で覚える。", scene: "1年間休まず働いた父に、家族全員が拍手して温泉旅行のチケットをわたす。", flow: ["見合ったものを受ける", "～に値する", "罰を受けて当然"], parts: [["de", "すっかり"], ["serve", "仕える"]], pair: "deserve は「もらって当然」、earn は「働いて実際に手に入れる」。" },
    "detect": { hint: "ディテクティブ（探偵）が持っている力", core: "かくれているものの『おおいを取って見つけ出す』。部屋のわずかな煙を機械がとらえる。", tip: "de（取る）＋tect（おおう）＝おおいを取る。detective（探偵）も同じ。", pic: "📡", scene: "天井の小さな機械が、トーストのこげたにおいにピピピッと鳴り出す。", flow: ["おおいを取る", "見つけ出す", "煙・病気を感知する"], parts: [["de", "取りのぞく"], ["tect", "おおう"]], fam: ["detective（探偵）", "detector（探知機）"], pair: "find は「見つける」全般、detect は「かくれた小さなものを見つける」。" },
    "determine": { hint: "term（期間・区切り）の仲間が入っている", core: "『境目を決めて、一つにしぼる』。いくつかの検査で、頭痛の本当の原因をつきとめる。", tip: "de（すっかり）＋termine（境界）。term（期間）・terminal（終点）と同じ。", scene: "医者がレントゲンを何枚も光にかざし、頭痛の原因を一つにしぼりこんでいく。", flow: ["境目を決める", "原因などを特定する", "決定する・決心する"], parts: [["de", "すっかり"], ["termine", "境界"]], fam: ["term（期間・区切り）", "terminal（終点）"], pair: "decide は「心を決める」、determine は「調べて決める・はっきりさせる」。" },
    "devote": { hint: "vote（誓い・投票）が入っている", core: "自分の時間や命を『すっかり〇〇のために使う』。一生を子どもたちのために使う。devote A to B の形。", tip: "de（すっかり）＋vote（誓う）＝誓って身をささげる。vote と同じ語源。", scene: "白髪のおばあさんが、アフリカの村の子どもたちにかこまれ、今日も勉強を教えている。", flow: ["誓って身をささげる", "時間・一生を～にささげる"], parts: [["de", "すっかり"], ["vote", "誓う"]], fam: ["vote（投票）", "devotion（献身）"], pair: "devote は「自分から全部ささげる」、dedicate は「献じる」で本などにも使う。" },
    "disturb": { hint: "ホテルのドアにかける『Do not ___』の札", core: "静かなものを『かき乱す』。大きな声で、ほかの乗客の静けさを乱す。", tip: "dis（すっかり）＋turb（乱す）。turbulence（乱気流）と同じ仲間。", pic: "🔊", scene: "静かな電車の中で、大声で電話する人のせいで、ねむっていた赤ちゃんが泣き出す。", flow: ["かき乱す", "人のじゃまをする", "心を不安にさせる"], parts: [["dis", "すっかり"], ["turb", "乱す"]], fam: ["turbulence（乱気流）", "disturbance（妨害）"], pair: "bother は「わずらわしく思わせる」、disturb は「静けさを乱す」。" },
    "donate": { hint: "駅前の募金箱に、おこづかいの百円玉をそっと入れる", core: "見返りなしに『差し出してあげる』。家を失った家族に食べ物や服をあげる。", tip: "don＝『与える』。donor（ドナー）と同じ仲間。", pic: "🎁", scene: "被災地へ送る段ボールに、近所の人たちが毛布や缶づめを次々と入れていく。", flow: ["見返りなしに差し出す", "お金・物を寄付する", "血・臓器を提供する"], parts: [["don", "与える"], ["ate", "～する"]], fam: ["donor（ドナー）", "donation（寄付）"], pair: "give は「あげる」全般、donate は「団体などに無償で寄付する」。" },
    "eliminate": { hint: "予選で負けたチームは大会から外される", core: "『外へ追い出してなくす』。食堂からペットボトルをなくす。試合で敗退するのも同じ。", tip: "e（外へ）＋limin（しきい）＝しきいの外へ出す。", pic: "🚫", scene: "食堂の自動販売機からペットボトルが消え、かわりに水のみ場が置かれた。", flow: ["しきいの外へ出す", "取り除く・なくす", "試合で敗退させる"], parts: [["e", "外へ（ex）"], ["limin", "しきい"], ["ate", "～する"]], fam: ["elimination（除去）"], pair: "remove は「その場から動かす」、eliminate は「完全になくす」。" },
    "emerge": { hint: "水の中から、ぬっと顔を出すイメージ", core: "かくれていたものが『外へ出てくる』。新しいシステムを使ったら、問題が表に出てきた。", tip: "e（外へ）＋merge（ひたる・沈む）。emergency（緊急事態）も同じ仲間。", pic: "🐣", scene: "静かな湖の水面がゆれ、カバの大きな頭がぬうっと上がってくる。", flow: ["水中から外へ出る", "姿を現す", "問題・事実が出てくる"], parts: [["e", "外へ（ex）"], ["merge", "ひたる"]], fam: ["emergency（緊急事態）", "merge（合併する）"], pair: "appear は「見えてくる」全般、emerge は「かくれていた所から出てくる」。" },
    "emphasize": { hint: "大事なところに太字や下線をつけるイメージ", core: "『ここが大事！』と目立たせる。コーチが、よくねむる大切さをくり返し言う。", tip: "名詞は emphasis。発音は最初の em を強く読む。", scene: "コーチがホワイトボードの『睡眠』の字を赤ペンで何重にも丸でかこむ。", flow: ["目立たせる", "大切さを強調する"], fam: ["emphasis（強調）"], pair: "stress も「強調する」だが、emphasize のほうがかたい言い方。" },
    "encounter": { hint: "counter（向かい合って）が入っている", core: "思いがけず『向かい合ってしまう』。山を下りる途中でクマとばったり。困難にも使う。", tip: "en（中に）＋counter（反対に・向かって）＝向こうから来たものと向き合う。", pic: "🐻", scene: "山道のカーブを曲がったとたん、目の前に大きなクマが立っていて、思わず足が止まる。", flow: ["思いがけず向き合う", "人・動物に出くわす", "困難にぶつかる"], parts: [["en", "中に"], ["counter", "向かって"]], pair: "meet は「会う」全般、encounter は「思いがけず出くわす」。" },
    "enhance": { hint: "すでによいものを、さらに一段上へ", core: "もとのよさを『さらに上へ引き上げる』。ハーブを入れると、スープの味がぐっとよくなる。", tip: "en（～にする）＋hance（高い）。ラテン語 altus（高い）が変化した形がもと。", scene: "シンプルなスープに、刻んだバジルをひとつまみ入れると、香りがぐっと広がる。", flow: ["さらに上へ引き上げる", "価値・味を高める"], fam: ["enhancement（向上）"], pair: "improve は「悪い点を直してよくする」、enhance は「よいものをさらによく」。" },
    "ensure": { hint: "出かける前に、ガスの元栓が閉まっているか必ず見ておく", core: "『確かにそうなるようにする』。全員が安全であるように、シートベルトを確かめる。", tip: "en（～にする）＋sure（確か）＝確かにする。make sure とほぼ同じ。", scene: "ジェットコースターの係員が、一人ずつ安全バーをガチャッと引いて確かめる。", flow: ["確かにそうする", "安全などを確実にする"], parts: [["en", "～にする"], ["sure", "確かな"]], fam: ["insure（保険をかける）", "assure（保証する）"], pair: "ensure は「確実にする」、insure は「保険をかける」。" },
    "estimate": { hint: "工事の前に『だいたいいくら・どのくらい』を出す", core: "正確ではないが『だいたいの量や値段を出す』。城の修理に約5年かかると考える。", tip: "esteem（尊重する）と同じ語源で『ねうちをはかる』がもと。", scene: "工事の人が古いお城の石垣を見上げ、指を折って『5年はかかるな』とつぶやく。", flow: ["ねうちをはかる", "量・費用を見積もる"], fam: ["esteem（尊重する）", "estimation（評価）"], pair: "calculate は「正確に計算する」、estimate は「だいたいで見積もる」。" },
    "evaluate": { hint: "先生が作文を読んで、A・B・C の印をつける", core: "どのくらい『価値があるかを判断する』。スピーチの内容や話し方を見て点をつける。", tip: "e（外へ）＋value（価値）＝価値を引き出して決める。", pic: "💯", scene: "スピーチ大会で、審査員がペンを持ち、話す人の声や内容に点数をつけていく。", flow: ["価値を引き出して決める", "評価する・判断する"], parts: [["e", "外へ（ex）"], ["valu", "価値"], ["ate", "～する"]], fam: ["value（価値）", "evaluation（評価）"], pair: "appreciate は「よさがわかる」、evaluate は「基準で点をつける」。" },
    "expand": { hint: "風船のように、ふくらんで大きく広がる", core: "『外へ広がって大きくなる』。お店を2つ増やして商売を広げる。", tip: "ex（外へ）＋pand（広げる）。名詞は expansion。", pic: "🎈", scene: "人気のパン屋さんが、となりの空き店舗の壁をこわし、お店を2倍に広げる。", flow: ["外へ広がる", "事業・規模を拡大する", "ふくらむ"], parts: [["ex", "外へ"], ["pand", "広げる"]], fam: ["expansion（拡大）"], pair: "extend は「長くのばす」、expand は「四方に広げて大きくする」。" },
    "expose": { hint: "おおいを取って、外に出しっぱなしにする", core: "おおいをとって『外に置き、当てる』。はだを強い日光に当てる。秘密をあばくのも同じ。", tip: "ex（外へ）＋pose（置く）。写真の『露出』は exposure。", pic: "☀️", scene: "真夏の海辺で、日焼け止めもぬらずに背中を太陽にさらしたまま寝てしまう。", flow: ["おおいを取って外に置く", "日光・危険にさらす", "秘密をあばく"], parts: [["ex", "外へ"], ["pose", "置く"]], fam: ["exposure（さらすこと・露出）"], pair: "show は「見せる」、expose は「かくれていたものをむき出しにする」。" },
    "extend": { hint: "髪を長くする『エクステ』", core: "『外へのばす』。テスト前に図書館の開館時間を後ろへのばす。手や道をのばすのも同じ。", tip: "ex（外へ）＋tend（のばす）。エクステ＝extension（のばすもの）。", scene: "テスト前の図書館で、『今週は夜9時まで開館』という紙がはり出される。", flow: ["外へのばす", "期間・時間を延長する", "手・道を広げる"], parts: [["ex", "外へ"], ["tend", "のばす"]], fam: ["extension（延長）", "extent（範囲）"], pair: "extend は「長くのばす」、expand は「大きく広げる」。" },
    "fulfill": { hint: "器を満タンにするイメージ。夢や約束に使う", core: "あいている所を『いっぱいに満たす』。子どものころの夢を満たす→かなえる、約束を満たす→果たす。", tip: "full（いっぱい）＋fill（満たす）。器を満タンにするイメージ。", scene: "空港で、制服を着た青年が、小さいころに描いたパイロットの絵を手に操縦席へ向かう。", flow: ["いっぱいに満たす", "夢・望みをかなえる", "約束・義務を果たす"], parts: [["ful", "いっぱい（full）"], ["fill", "満たす"]], fam: ["fulfillment（実現）"], pair: "achieve は「努力して達成する」、fulfill は「夢・約束を満たす」。" },
    "generate": { hint: "ジェネレーター（発電機）", core: "『生み出す』。風車が300軒分の電気を生み出す。アイデアや利益にも使う。", tip: "gen（生む）。generation（世代）・gene（遺伝子）と同じ仲間。", pic: "⚡", scene: "丘の上で風車の羽根がゆっくり回り、ふもとの町の家々に明かりがともる。", flow: ["生み出す", "電気・熱を発生させる", "利益・考えを生む"], parts: [["gener", "生む"], ["ate", "～する"]], fam: ["generator（発電機）", "generation（世代）", "gene（遺伝子）"], pair: "produce は「作り出す」全般、generate は「電気・熱などを発生させる」。" },
    "hesitate": { hint: "足が止まって、なかなか一歩が出ない", core: "迷って『その場にくっついて動けない』。don't hesitate to ～＝えんりょなく～してください。", tip: "ラテン語 haerere（くっつく）から。迷って足がその場にはりつく感じ。", scene: "プールの飛びこみ台の先で、少年が下をのぞきこみ、足がはりついたまま動けない。", flow: ["その場にくっつく", "迷ってためらう", "don't hesitate で遠慮なく"], fam: ["hesitation（ためらい）"], pair: "hesitate は「迷って止まる」、refuse は「はっきり断る」。" },
    "identify": { hint: "ID（身分証明書）を思い出そう", core: "『だれ（何）なのかを確かめてはっきりさせる』。カメラの映像から運転手がだれかをつきとめる。", tip: "ID カードの ID は identification（身元確認）の略。", pic: "🆔", scene: "警察官が防犯カメラの映像を止め、運転席の男の顔を写真と一枚ずつ見比べる。", flow: ["同じだと確かめる", "人・物を特定する", "見分ける"], parts: [["ident", "同じ"], ["ify", "～にする"]], fam: ["identity（身元・正体）", "identical（まったく同じ）"], pair: "recognize は「見て思い出す」、identify は「だれ・何かをつきとめる」。" },
    "illustrate": { hint: "イラスト（絵）", core: "絵や例で『光を当てて、わかりやすくする』。かんたんな絵で心臓のしくみを見せる。", tip: "il（中に）＋lustr（光を当てる）。illustration（イラスト）と同じ。", pic: "🖼️", scene: "先生が黒板に心臓の絵をかき、血の流れを矢印でたどりながら話す。", flow: ["光を当てる", "絵・例でわかりやすく説明", "挿絵を入れる"], parts: [["il", "中に（in）"], ["lustr", "光を当てる"], ["ate", "～する"]], fam: ["illustration（イラスト・例）"], pair: "explain は「言葉で説明する」、illustrate は「例や図で示す」。" },
    "impose": { hint: "上から、ずしりと『置く』イメージ", core: "上から『おしつけて置く』。政府が甘い飲み物に新しい税をのせる。ルールや罰にも使う。", tip: "im（上に）＋pose（置く）。expose（外に置く）と同じ pose。", scene: "大臣が、甘いジュースの山の上に『税』と書かれた重い石をドンとのせる絵。", flow: ["上からおしつけて置く", "税・罰を課す", "考えをおしつける"], parts: [["im", "上に（in）"], ["pose", "置く"]], fam: ["expose（さらす）", "propose（提案する）"], pair: "impose は「上からおしつける」、propose は「前に置いて提案する」。" },
    "indicate": { hint: "インジケーター（ランプで状態を知らせるもの）", core: "『指でさすように知らせる』。研究が『歩くとストレスが減る』ことを指し示す。", tip: "in（～へ）＋dic（言う・示す）。index（人差し指・索引）も仲間。", pic: "👉", scene: "研究者がグラフの右下がりの線を指でさし、『ほら、歩くとストレスが減る』と示す。", flow: ["指でさして知らせる", "示す・表す", "それとなく示す"], parts: [["in", "～へ"], ["dic", "示す・言う"], ["ate", "～する"]], fam: ["index（索引）", "indicator（指標）"], pair: "show は「見せる」、indicate は「しるしで指し示す」。" },
    "inspire": { hint: "spire は『息』。心に息をふきこむ", core: "心に『息をふきこむ』。彼女のスピーチが若者にやる気をふきこみ、ボランティアを始めさせた。", tip: "in（中へ）＋spire（息をする）。インスピレーション（ひらめき）も同じ。", scene: "講演が終わると、聞いていた高校生たちの目が輝き、すぐにボランティアに申しこむ。", flow: ["心に息をふきこむ", "やる気を起こさせる", "ひらめきを与える"], parts: [["in", "中へ"], ["spire", "息をする"]], fam: ["inspiration（ひらめき）", "spirit（精神）"], pair: "encourage は「はげます」、inspire は「心に火をつけて動かす」。" },
    "install": { hint: "パソコンにアプリを入れるときにも使う", core: "決まった場所に『しっかり置いて、使えるようにする』。屋根にソーラーパネルをつける。", tip: "in（中に）＋stall（置き場所）。カタカナの『インストール』で覚える。", pic: "🔩", scene: "作業員が屋根にのぼり、太陽光パネルを一枚ずつボルトでしっかりとめていく。", flow: ["決まった場所に置く", "機械を設置する", "ソフトを入れる"], parts: [["in", "中に"], ["stall", "置き場所"]], fam: ["installation（設置）"], pair: "put は「置く」、install は「使えるようにすえつける」。" },
    "interpret": { hint: "同じ絵でも、人によって『意味の受け取り方』がちがう", core: "間に立って『意味をときほぐして伝える』。絵の意味を自分なりに読みとる。言葉の間に立てば通訳。", tip: "inter（間に）がつく。間に入って意味をつなぐ人が interpreter。", scene: "美術館で、同じ絵の前に立つ二人が、一人は『悲しい絵』、一人は『希望の絵』と言う。", flow: ["間に立って意味をとく", "意味を解釈する", "言葉を通訳する"], parts: [["inter", "間に"], ["pret", "取引する"]], fam: ["interpreter（通訳者）", "interpretation（解釈）"], pair: "translate は「文章を訳す」、interpret は「話し言葉を通訳する・意味を読みとる」。" },
    "interrupt": { hint: "inter（間に）がつく。話の途中に…", core: "話や動きの『間に割って入る』。話の途中に入って『電話ですよ』と伝える。", tip: "inter（間に）＋rupt（破る）。bankrupt（破産した）と同じ rupt。", scene: "会議で部長が話している最中、ドアが開いて『お電話です』と声がかかる。", flow: ["間に割って入る", "話をさえぎる", "作業を中断する"], parts: [["inter", "間に"], ["rupt", "破る"]], fam: ["bankrupt（破産した）", "erupt（噴火する）"], pair: "disturb は「静けさを乱す」、interrupt は「途中で割りこんで止める」。" },
    "enroll": { hint: "春、新しい学校や講座のメンバーとして正式に名前が入る", core: "『名簿に名前を書き入れる』。オンライン講座の名簿に名前が入る→申しこむ・入学する。", tip: "en（中に）＋roll（巻き物・名簿）。roll call（出席をとる）の roll。", pic: "📝", scene: "春、新入生が受付の名簿に自分の名前を書きこみ、学生証を受け取る。", flow: ["名簿に名前を入れる", "入学する", "講座に登録する"], parts: [["en", "中に"], ["roll", "名簿"]], fam: ["enrollment（入学・登録）"], pair: "enter は「入る」全般、enroll は「正式に名簿に登録する」。" },
    "maintain": { hint: "車を定期的に点検に出して、よく走る状態を続ける", core: "『手で持ち続ける』。よい健康をずっと保つ。意見を変えずに持ち続けるのも同じ。", tip: "main（手）＋tain（保つ）。maintenance（メンテナンス）と同じ。", scene: "毎朝6時、おじいさんが公園を一周走り、80歳でも同じ体重と元気を保っている。", flow: ["手で持ち続ける", "状態を維持する", "意見を主張し続ける"], parts: [["main", "手"], ["tain", "保つ"]], fam: ["maintenance（メンテナンス）", "obtain（手に入れる）"], pair: "keep は「保つ」全般、maintain は「手をかけてよい状態を保つ」。" },
    "modify": { hint: "全部作り直さず、一部に手を入れる", core: "もとの形を残して『一部を手直しする』。燃料が少なくてすむよう、車の設計を直す。", tip: "mod（はかる・型）。mode（型）・model（模型）と同じ仲間。", pic: "🛠️", scene: "技術者が車の設計図に赤ペンでいくつか線を足し、エンジンの形を少しだけ変える。", flow: ["型に合わせて手直し", "一部を修正する"], parts: [["mod", "はかる・型"], ["ify", "～にする"]], fam: ["mode（型）", "model（模型）"], pair: "change は「変える」全般、modify は「少し手直しする」。" },
    "negotiate": { hint: "値段を下げてほしい客と店主が、何度も数字を言い合う", core: "相手と『話し合って条件を決める』。給料や休みについて会社と話をつめる。", tip: "ラテン語 negotium（仕事・取り引き）から。ビジネス用語の『ネゴ』。", pic: "💬🤝", scene: "長い机をはさみ、組合の代表と社長が、給料の数字を何度も書き直して話し合う。", flow: ["仕事・取り引きをする", "条件を話し合う", "交渉してまとめる"], fam: ["negotiation（交渉）"], pair: "discuss は「話し合う」、negotiate は「おたがい条件を出して決める」。" },
    "obtain": { hint: "許可や情報を、手続きや努力で『もらう』", core: "努力や手続きで『自分の手に持つ』。イベントの前に市から許可をもらう。", tip: "ob（～に向かって）＋tain（保つ・持つ）。maintain と同じ tain。", pic: "🎫", scene: "イベントの前に、市役所の窓口で書類を出し、許可のハンコをもらう。", flow: ["自分の手に持つ", "許可・情報を手に入れる"], parts: [["ob", "～に向かって"], ["tain", "持つ"]], fam: ["maintain（維持する）", "contain（ふくむ）"], pair: "get と同じだが、obtain は手続きや努力で「得る」かたい語。" },
    "occupy": { hint: "トイレの表示『OCCUPIED（使用中）』", core: "場所を『とって、そこにいる』。森が日本の土地の3分の2をとっている。時間や心をうめるのも同じ。", tip: "トイレや飛行機の『使用中』は occupied。場所がふさがっている。", pic: "🪑", scene: "昼休みの食堂で、窓ぎわの席が全部カバンでうまっていて、座る場所がない。", flow: ["場所をとってそこにいる", "割合・場所を占める", "時間・心をうめる"], fam: ["occupation（職業・占領）"], pair: "occupy は「場所をふさぐ」、possess は「持っている」。" },
    "participate": { hint: "part（部分）が入っている", core: "全体の『一部分になる』。ビーチ清掃の一員になる。participate in ～の形。", tip: "parti（部分）＋cip（取る）＝一部を受け持つ。take part in と同じ意味。", pic: "🧩", scene: "日曜の朝、50人の生徒がそろいのTシャツで並び、ビーチのごみを拾い始める。", flow: ["一部を受け持つ", "活動に参加する"], parts: [["parti", "部分"], ["cip", "取る"], ["ate", "～する"]], fam: ["part（部分）", "participant（参加者）"], pair: "join は「仲間に入る」、participate in は「活動に参加する」。" },
    "exaggerate": { hint: "釣った魚を、両手を広げて実際の倍の大きさで話す", core: "『実際より大きく積み上げて言う』。どれだけ勉強したかを大げさに話す。", tip: "ラテン語 agger（積み上げた土）から。話を山のように積み上げるイメージ。", scene: "『テスト前は48時間ねないで勉強した！』と、クラスで胸を張る男子。", flow: ["土を高く積み上げる", "実際より大げさに言う"], parts: [["ex", "すっかり"], ["agger", "積み上げる"], ["ate", "～する"]], fam: ["exaggeration（誇張）"], pair: "lie は「うそをつく」、exaggerate は「本当のことを大きく言う」。" },
    "postpone": { hint: "post（後に）が入っている", core: "予定を『後ろに置く』。大雨で試合を次の日曜に回す。put off と同じ。", tip: "post（後に）＋pone（置く）。post- は postwar（戦後）にも。", pic: "📅➡️", scene: "雨でぬかるんだグラウンドに、『試合は来週日曜に』と書かれた紙がはられる。", flow: ["後ろに置く", "予定を延期する"], parts: [["post", "後に"], ["pone", "置く"]], fam: ["postwar（戦後の）"], pair: "postpone は「日をずらす」、cancel は「とりやめる」。" },
    "imitate": { hint: "イミテーション（にせもの）", core: "『同じようにやってみる』。子どもは親の動きを写しとって学ぶ。", tip: "名詞は imitation（イミテーション＝本物に似せたもの）。", pic: "🦜", scene: "2歳の女の子が、ママのまねをしてスマホを耳にあて、『もしもし』と言っている。", flow: ["同じようにやってみる", "まねる・手本にする"], fam: ["imitation（にせもの・まね）"], pair: "copy は「写しとる」、imitate は「動きや話し方をまねる」。" },
    "preserve": { hint: "古い家を『今のまま』未来へ残すイメージ", core: "こわれないよう『そのままの形で守って残す』。古い木の家を次の世代へ。食べ物を長持ちさせるのも同じ。", tip: "pre（前もって）＋serve（ラテン語 servare＝守る）。プリザーブドフラワーも同じ。", pic: "🏯", scene: "古い町並みで、大工さんが昔と同じ木と同じ形で、くさった柱を一本だけ取りかえる。", flow: ["そのまま守って残す", "建物・自然を保護する", "食べ物を保存する"], parts: [["pre", "前もって"], ["serve", "守る（servare）"]], fam: ["reserve（予約する）", "conserve（保存する）"], pair: "protect は「危険から守る」、preserve は「今の形のまま残す」。" },
    "inherit": { hint: "親や祖父母から、次の人へわたっていくもの", core: "前の世代から『受け取って自分のものになる』。祖母の家をもらう。性格や才能にも使う。", tip: "ラテン語 heres（あととり）から。heir（相続人）と同じ仲間。", scene: "おばあさんの家の鍵を受け取った孫が、縁側に立って庭の柿の木を見上げる。", flow: ["あととりが受け取る", "財産を相続する", "性質を受け継ぐ"], fam: ["heir（相続人）", "heritage（遺産）"], pair: "inherit は「前の人から受け継ぐ」、receive は「受け取る」全般。" },
    "prohibit": { hint: "病院の入口の、たばこに赤い斜線のマーク", core: "前に立ちはだかって『させないようにする』。病院中でタバコはダメ。", tip: "pro（前に）＋hibit（持つ・おさえる）＝前でおさえて止める。", pic: "🚭", scene: "プールサイドの看板に『走らない・飛びこまない』と赤い大きな字で書いてある。", flow: ["前でおさえて止める", "法・規則で禁止する"], parts: [["pro", "前に"], ["hibit", "おさえる"]], fam: ["prohibition（禁止）", "exhibit（展示する）"], pair: "forbid は「（人が）禁じる」、prohibit は「法・規則で禁止する」。" },
    "promote": { hint: "プロモーション（宣伝活動）", core: "『前へ動かす』。公共交通を使う人が増えるよう後押しする。人を上の地位へ動かす→昇進。", tip: "pro（前へ）＋mote（動かす）。motor（モーター）と同じ mot。", pic: "⏫", scene: "駅前でキャンペーンのチラシを配り、『バスに乗ろう』と人々の背中を押す。", flow: ["前へ動かす", "活動を促進する", "地位を上げる→昇進"], parts: [["pro", "前へ"], ["mote", "動かす"]], fam: ["promotion（昇進・宣伝）", "motor（モーター）", "remote（遠い）"], pair: "advertise は「広告する」、promote は「広める・前に進める」。" },
    "pursue": { hint: "夢や仕事に向かって、ずっと進み続ける", core: "目標を『追いかけ続ける』。音楽の仕事をめざして東京へ。犯人を追うのも同じ。", tip: "ラテン語 prosequi（前へついて行く）から。名詞は pursuit。", pic: "🏃💨", scene: "ギターをかついだ青年が、夜行バスの窓から東京の明かりをじっと見つめている。", flow: ["あとを追いかける", "夢・目標を追い求める", "研究を続ける"], fam: ["pursuit（追求）"], pair: "chase は「物理的に追いかける」、pursue は「夢や目標を追い続ける」。" },
    "qualify": { hint: "試合に勝って、次の大会への『切符』を手に入れる", core: "必要な『条件をみたして、出られる・できる』。勝って全国大会への出場が決まった。", tip: "名詞 qualification（資格）。quality（質）と同じ語源。", pic: "🎟️", scene: "決勝点が入った瞬間、選手たちが抱き合い、スコアボードに『全国大会へ』と出る。", flow: ["条件を満たす", "出場資格を得る", "資格を与える"], parts: [["quali", "どんな性質"], ["fy", "～にする"]], fam: ["qualification（資格）", "quality（質）"], pair: "qualify は「資格を得る」、quantity は「量」で別の語。" },
    "regulate": { hint: "人の多い町の空で、ドローンが自由に飛べないよう決まりを作る", core: "『ルールで動きをコントロールする』。人の多い所でのドローンに決まりを作る。温度の調整も同じ。", tip: "ラテン語 regula（ものさし・きまり）から。regular（規則正しい）と同じ仲間。", pic: "🚦", scene: "交差点のまん中で、警官が笛をふき、車の流れを手で止めたり進めたりしている。", flow: ["ものさしで整える", "規則で規制する", "温度・量を調整する"], fam: ["regulation（規則）", "regular（規則正しい）"], pair: "control は「思い通りに動かす」、regulate は「規則で決まった範囲におさえる」。" },
    "reflect": { hint: "鏡や水面に、すがたがうつるイメージ", core: "『はね返して、うつし出す』。光がはね返る→反射、みんなの意見が新しいルールにうつし出される→反映する。", tip: "re（もとへ）＋flect（曲げる）。リフレクター（反射板）。", pic: "🪞", scene: "風のない朝、湖の水面に、まわりの山と赤い紅葉がさかさまにくっきりうつる。", flow: ["光をはね返す", "反射する・うつす", "意見を反映する", "よく考える"], parts: [["re", "もとへ"], ["flect", "曲げる"]], fam: ["reflection（反射・反映）", "flexible（曲げやすい）"], pair: "reflect は「うつし出す」、affect は「影響を与える」。" },
    "reject": { hint: "ject（投げる）が入っている", core: "『投げ返す』。わたしのアイデアを受け取らず、つき返す。", tip: "re（もとへ）＋ject（投げる）。project（前に投げる→計画）と同じ ject。", scene: "会議で出した企画書を、部長が読まずに机の上でスッとこちらへ押し返す。", flow: ["投げ返す", "案・申し出を拒否する"], parts: [["re", "もとへ"], ["ject", "投げる"]], fam: ["project（計画）", "inject（注射する）"], pair: "refuse は「断る」全般、reject は「出されたものをつき返す」。" },
    "release": { hint: "CD やゲームの『リリース日』", core: "閉じこめていたものを『ときはなつ』。動物を放す、新しいアルバムを世に出す。", tip: "カタカナの『リリース』。つかんでいた手をパッと開くイメージ。", pic: "🕊️", scene: "浜辺で、子どもたちが育てた子ガメを、そっと手から波打ちぎわへ放す。", flow: ["にぎった手を開く", "動物・人を放す", "新作を発表する"], pair: "release は「放す・世に出す」、relax は「力をぬく」。" },
    "resign": { hint: "大きな失敗の責任をとって、地位から身を引く", core: "持っていた地位を『手放してしりぞく』。会社が大損をして、責任者がやめる。", tip: "名詞は resignation。re-sign（もう一度サインする）とは別の語。", scene: "記者会見で、部長が深く頭を下げ、机の上に辞表の白い封筒を置く。", flow: ["地位を手放す", "仕事を辞職する"], fam: ["resignation（辞職）"], pair: "retire は「年齢で引退する」、resign は「自分から地位をやめる」。" },
    "revise": { hint: "vise は『見る』。もう一度…", core: "『もう一度見直して直す』。本を見直して、新しい章を2つ足す。", tip: "re（もう一度）＋vise（見る）。vision（視野）と同じ vis。", pic: "✏️", scene: "作家がむかし書いた本のページを読み返し、赤ペンで直しを入れ、新しい章を足す。", flow: ["もう一度見直す", "文章を改訂する", "計画を修正する"], parts: [["re", "もう一度"], ["vise", "見る"]], fam: ["revision（改訂）", "vision（視野）"], pair: "correct は「まちがいを正す」、revise は「見直して書き改める」。" },
    "strengthen": { hint: "strong（ストロング）が形を変えて入っている", core: "『もっと強くする』。古いビルを大地震にたえられるよう強くする。", tip: "strength（強さ）＋en（～にする）。short→shorten と同じ作り。", pic: "💪", scene: "古いビルの壁に、作業員が太い鉄の柱をななめに何本も取り付けていく。", flow: ["もっと強くする", "建物・関係を強化する"], parts: [["strength", "強さ"], ["en", "～にする"]], fam: ["strength（強さ）", "lengthen（のばす）"], pair: "strengthen は「強くする」、weaken は「弱くする」で反対。" },
    "tolerate": { hint: "いやなことでも『まあ、いいか』と受け止める", core: "いやなものを『受け止めて、たえる』。先生は授業中のスマホを見のがさない。", tip: "名詞は tolerance（寛容）。ラテン語 tolerare（たえる）から。", scene: "授業中、机の下でスマホを光らせた生徒の前に、先生が無言で手を差し出す。", flow: ["受け止めてたえる", "我慢する", "（大目に見て）容認する"], fam: ["tolerance（寛容）", "tolerant（寛大な）"], pair: "stand・bear も「我慢する」。tolerate は「認めて許す」かたい語。" },
    "restore": { hint: "こわれたものを、昔の姿にもどす", core: "『もとの状態にもどす』。火事のあとの教会を昔の姿に。体力や信頼をとりもどすのも同じ。", tip: "re（もとへ）がポイント。パソコンの『リストア（復元）』と同じ。", scene: "火事で黒くなった教会の壁を、職人が2年かけて昔の白い姿にもどしていく。", flow: ["もとの状態にもどす", "建物を修復する", "健康・信頼を回復させる"], fam: ["restoration（修復）"], pair: "repair は「こわれた所を直す」、restore は「もとの姿にもどす」。" },
    "retire": { hint: "長く働いたあと、表舞台から後ろへ下がる", core: "表から『後ろへ引っこむ』。65歳で仕事から下がり、野菜作りを始めた。", tip: "re（後ろへ）＋tire（引く）。tire（疲れる）とは別の語。", pic: "🏡", scene: "最後の出勤日、花束をかかえた祖父が会社を出て、次の日から畑で野菜を育てる。", flow: ["後ろへ引っこむ", "仕事を退職する", "選手が引退する"], fam: ["retirement（退職）"], pair: "resign は「途中で辞職する」、retire は「年齢・区切りで引退する」。" },
    "reveal": { hint: "veil（ベール）を取るイメージ", core: "かくれていたものの『ベールをはがして見せる』。調査で、朝ごはんを食べない生徒が多いとわかった。", tip: "re（反対に）＋veal（ベール）＝ベールを外す。", scene: "ステージで布がバサッと取られ、下からぴかぴかの新車が現れる。", flow: ["ベールを外す", "かくれた事実を明らかにする", "秘密を打ち明ける"], fam: ["revelation（暴露・発見）", "veil（ベール）"], pair: "show は「見せる」、reveal は「かくれていたものを見せる」。" },
    "satisfy": { hint: "satis は『十分』という意味", core: "相手の求めを『十分にみたす』。肉を食べないお客の希望に合うメニューにする。", tip: "satis（十分）＋fy（～にする）。名詞は satisfaction。", pic: "😋", scene: "肉を食べない客が、新メニューの野菜カレーを一口食べて、にっこりうなずく。", flow: ["十分にみたす", "人を満足させる", "条件を満たす"], parts: [["satis", "十分"], ["fy", "～にする"]], fam: ["satisfaction（満足）"], pair: "satisfied は「満足した」、satisfying は「満足させる」。" },
    "submit": { hint: "sub（下に）がつく。先生の手元へわたす場面", core: "相手の『下に送りわたす』。作文を金曜までに先生にわたす。相手に従う意味もある。", tip: "sub（下に）＋mit（送る）。admit・permit と同じ mit。", pic: "📤", scene: "締め切りの金曜5時、職員室の先生の机に、作文の束をそっと置く。", flow: ["下に送りわたす", "書類を提出する", "相手に従う"], parts: [["sub", "下に"], ["mit", "送る"]], fam: ["admit（認める）", "permit（許す）"], pair: "hand in と同じ意味。submit のほうがかたい。" },
    "transform": { hint: "トランスフォーマー（変身ロボット）", core: "『形をすっかり別のものへ移す』。スマホが写真のとり方・共有のしかたをがらりと変えた。", tip: "trans（向こうへ）＋form（形）。形がまるごと変わる。", pic: "🐛➡️🦋", scene: "フィルムカメラをかまえていた人たちが、今はスマホで撮ってすぐ世界中に送る。", flow: ["形を向こうへ移す", "すっかり変える・一変させる"], parts: [["trans", "向こうへ"], ["form", "形"]], fam: ["transformation（変化）", "form（形）"], pair: "change は「変える」全般、transform は「見ちがえるほど変える」。" },
    "sustain": { hint: "SDGs でよく聞く『サステナブル』", core: "下から『ささえ続ける』。新しい仕事がないと、村は人口をささえ続けられない。", tip: "sus（下から）＋tain（保つ）＝下から支える。maintain と同じ tain。", scene: "山奥の村で、若者が始めたカフェに人が集まり、学校の明かりがまだ消えずにいる。", flow: ["下からささえる", "生活・人口を維持する", "持続させる"], parts: [["sus", "下から（sub）"], ["tain", "保つ"]], fam: ["sustainable（持続可能な）", "maintain（維持する）"], pair: "maintain は「よい状態を保つ」、sustain は「ささえて長く続かせる」。" },

    // ===== 名詞 =====
    "agriculture": { hint: "culture（耕す）が入っている", core: "『畑を耕すこと』全体。米や野菜を育て、家畜を飼う仕事。", tip: "agri（畑）＋culture（耕すこと）。culture（文化）ももとは『耕す』。", pic: "🚜", scene: "朝もやの中、トラクターが田んぼを耕し、となりの牧場では牛が草を食べている。", flow: ["畑を耕すこと", "農業"], parts: [["agri", "畑"], ["culture", "耕すこと"]], fam: ["agricultural（農業の）", "culture（文化）"], pair: "farming も「農業」だが、agriculture は産業として見たかたい語。" },
    "alternative": { hint: "A がだめなら B、という『もう一つの道』", core: "『ほかに選べるもう一つの道』。自分の車で通う代わりになる方法を探す。", tip: "alter（もう一方の）から。alternate（交互の）と同じ仲間。", pic: "🔀", scene: "朝の大渋滞の横を、自転車に乗った会社員がすいすい追いこしていく。", flow: ["もう一方を選べる道", "代わりのもの・方法"], fam: ["alter（変える）", "alternate（交互の）"], pair: "substitute は「代役」、alternative は「選べるもう一つの案」。" },
    "atmosphere": { hint: "sphere（球）が入っている", core: "場所を『ぐるっと包む空気』。地球を包む空気→大気、お店を包む空気→雰囲気。", tip: "atmo（蒸気）＋sphere（球）＝地球を包むもや。", pic: "🌫️", scene: "木のカウンターに暖かい明かり、コーヒーの香りとジャズが店じゅうを包んでいる。", flow: ["地球を包む空気", "大気", "場所を包む雰囲気"], parts: [["atmo", "蒸気"], ["sphere", "球"]], fam: ["sphere（球）", "hemisphere（半球）"], pair: "atmosphere は「その場の空気・雰囲気」、environment は「環境」。" },
    "authority": { hint: "author（生み出した人）が入っている", core: "人を従わせる『力』と、その力を持つ人たち。町に指示を出す力を持つ所→当局、知識の力→権威。", tip: "author（作者）と同じ語源。ものごとを決められる人の力。", scene: "台風の前、市役所のスピーカーから『家から出ないでください』と放送が流れる。", flow: ["人を従わせる力", "権威・権限", "（the authorities）当局"], fam: ["author（作者）", "authorize（権限を与える）"], pair: "power は「力」全般、authority は「正式に認められた力」。" },
    "appliance": { hint: "台所や洗面所で、コンセントにつないで使う", core: "ある仕事に『あてて使う道具』。洗濯機・冷蔵庫など、家の中の電気の道具。", tip: "apply（あてはめる・使う）から。仕事に使う道具という意味。", pic: "🔌", scene: "引っこしの日、トラックから冷蔵庫・洗濯機・電子レンジが順に運びこまれる。", flow: ["仕事にあてて使う道具", "家庭用電化製品"], fam: ["apply（あてはめる）"], pair: "device は「装置」全般、appliance は「家庭用の電気器具」。" },
    "candidate": { hint: "選挙ポスターに顔がのっている人たち", core: "ある地位に『選ばれるのを待っている人』。市長選挙に出ている3人。", tip: "ラテン語 candidus（白い）から。ローマでは白い服を着て選挙に出た。", pic: "🗳️", scene: "選挙カーの上で、たすきをかけた人が手をふり、通りの人に名前をくり返し叫ぶ。", flow: ["選ばれるのを待つ人", "選挙の候補者", "採用の候補"], pair: "applicant は「応募者」、candidate は「候補者」として選ばれる側。" },
    "capacity": { hint: "cap は『つかむ・入れる』。スタジアムの4万人", core: "中に『入れられる量』。新しいスタジアムには4万人入る。人の力の大きさにも使う。", tip: "cap（つかむ・入れる）。capable（能力がある）と同じ仲間。", pic: "🏟️", scene: "4万席の観客席が、試合の日には一つ残らず人でうまっている。", flow: ["中に入れられる量", "収容人数・容量", "能力"], fam: ["capable（能力がある）", "capture（とらえる）"], pair: "ability は「人の能力」、capacity は「入る量・受け入れる力」。" },
    "circumstance": { hint: "circum は『まわり』（circle の仲間）", core: "自分の『まわりに立っているもの』＝まわりのようす。under no circumstances＝どんな場合でも～ない。", tip: "circum（まわり）＋stance（立つ）。circle（円）と同じ仲間。", scene: "夜中にドアのチャイムが鳴り、子どもが一人で留守番中、外は知らない声。", flow: ["まわりに立つもの", "状況・事情", "under no ~ で決して"], parts: [["circum", "まわり"], ["stance", "立つこと"]], fam: ["circle（円）", "distance（きょり）"], pair: "situation は「今の状況」、circumstances は「まわりの事情」で複数形が多い。" },
    "chemical": { hint: "カタカナで『ケミカル』。農薬や洗剤に入っているもの", core: "『化学の力で作られたもの』。農薬など、人工的な成分を指すことが多い。", tip: "chemistry（化学）と同じ仲間。『ケミカル』で覚える。", pic: "🧪", scene: "畑の農家が、白いタンクの農薬をやめ、虫を手で一匹ずつ取っている。", flow: ["化学の", "化学物質・薬品"], fam: ["chemistry（化学）", "chemist（化学者）"], pair: "chemical は「化学物質」、medicine は「（病気の）薬」。" },
    "committee": { hint: "学級会で選ばれた数人が、行事の準備をまかされる", core: "ある仕事を『まかされた人たちの集まり』。お祭りの準備をまかされたグループ。", tip: "commit（ゆだねる・まかせる）＋ee（される人）。", scene: "放課後の会議室で、祭りの係の8人がホワイトボードをかこんで計画を話し合う。", flow: ["仕事をまかされた人", "委員会"], parts: [["commit", "まかせる"], ["ee", "される人"]], fam: ["commit（ゆだねる）", "employee（従業員）"], pair: "committee は「委員会」、community は「地域社会」。" },
    "conflict": { hint: "2つのものが、ガツンとぶつかり合う", core: "2つのものが『ぶつかり合う』。2つのグループが長いあいだぶつかり続けた。", tip: "con（たがいに）＋flict（打つ）＝打ち合う。", pic: "⚔️", scene: "国境の川をはさんで、両側の兵士がにらみ合い、どちらも一歩も引かない。", flow: ["たがいに打ち合う", "意見の対立", "国どうしの紛争"], parts: [["con", "たがいに"], ["flict", "打つ"]], pair: "argument は「口げんか」、conflict は「長く続く対立・争い」。" },
    "consequence": { hint: "sequence（つながり・順番）が入っている", core: "あることの『あとについてくるもの』。木を切りすぎると、野生生物に悪いことが続いて起こる。", tip: "con（いっしょに）＋sequ（ついて行く）。sequel（続編）と同じ仲間。", scene: "山の木を全部切ったあと、大雨のたびに土砂が流れ、鳥の声も聞こえなくなった。", flow: ["あとについてくるもの", "結果", "（悪い）影響"], parts: [["con", "いっしょに"], ["sequ", "ついて行く"], ["ence", "こと"]], fam: ["sequence（順番）", "sequel（続編）"], pair: "result は「結果」全般、consequence は「（悪い）なりゆき・影響」。" },
    "contract": { hint: "プロのサッカー選手がチームとサインする書類", core: "両方が『引き寄せ合って結ぶ約束』。選手がスペインのチームと3年の約束を結ぶ。", tip: "con（いっしょに）＋tract（引く）。tractor（トラクター）と同じ tract。", pic: "📜", scene: "記者のフラッシュの中、新しいユニフォームを着た選手が書類にペンを走らせる。", flow: ["引き寄せて結ぶ", "契約・契約書"], parts: [["con", "いっしょに"], ["tract", "引く"]], fam: ["tractor（トラクター）", "attract（引きつける）"], pair: "promise は「約束」、contract は「法的な取り決め・契約」。" },
    "crisis": { hint: "うまくいくかだめになるか、ぎりぎりの分かれ目", core: "よくなるか悪くなるかの『分かれ目の、あぶない時』。石油が高くなり、国のエネルギーがあぶない。", tip: "ギリシャ語で『分かれ目・決断』。複数形は crises。", pic: "⚠️", scene: "ガソリンスタンドに『売り切れ』の札が並び、ニュースが一日中その話をしている。", flow: ["よしあしの分かれ目", "危機・重大な局面"], fam: ["critical（重大な）"], pair: "danger は「危険」、crisis は「どうなるかの分かれ目の危ない時」。" },
    "debt": { hint: "b は読まない（デット）。ローンやクレジットで増えていく", core: "『返さなければいけないもの』。銀行に10年かけて返した。", tip: "ラテン語 debitum（返すべきもの）に合わせて、後から b が足された。だから読まない。", pic: "💸", scene: "毎月の給料日、父が銀行の窓口でお金を少しずつ返し、通帳の残りの額が減っていく。", flow: ["返すべきもの", "借金・負債"], pair: "debt は「借金」、loan は「貸し付け（ローン）」。" },
    "decade": { hint: "デカスロン（十種競技）と同じ頭", core: "『10ずつのまとまり』の年。この10年で外国人観光客がとても増えた。", tip: "deca（10）。decathlon（十種競技）。December ももとは『10番目の月』。", pic: "🔟", scene: "駅前の写真を10年前と比べると、外国人観光客の姿がずっと多くなっている。", flow: ["10のまとまり", "10年間"], fam: ["decathlon（十種競技）"], pair: "decade は「10年」、century は「100年」。" },
    "demand": { hint: "冬になると、ストーブを買いたい人が一気に増える", core: "『強くほしいと求めること』。人が求める→要求、世の中が商品を求める量→需要。", tip: "de（強く）＋mand（命じる）。command（命令する）と同じ mand。", scene: "新しいゲーム機の発売日、お店の前に夜明け前から長い行列ができている。", flow: ["強く求めること", "要求", "商品への需要"], parts: [["de", "強く"], ["mand", "命じる"]], fam: ["command（命令する）"], pair: "demand は「需要」、supply は「供給」。セットで覚える。" },
    "conference": { hint: "ホテルの『カンファレンスルーム』", core: "人が『集まって意見を持ちよる』大きな会。20か国の医師が京都に集まる。", tip: "con（いっしょに）＋fer（運ぶ）＝意見を持ちよる。", scene: "大きなホールに20か国の医師が集まり、通訳のイヤホンをつけて発表を聞いている。", flow: ["意見を持ちよる", "（大きな）会議"], parts: [["con", "いっしょに"], ["fer", "運ぶ"], ["ence", "こと"]], fam: ["transfer（移す）", "offer（申し出る）"], pair: "meeting は「会議」全般、conference は「大規模で正式な会議」。" },
    "disaster": { hint: "aster は『星』。運の悪い星のもとで起こること", core: "多くの人がこまる『大きなわざわい』。地震や台風に備えて食べ物と水を用意する。", tip: "dis（悪い）＋aster（星）。星の位置が悪い＝不吉、から。asterisk（＊）も星。", pic: "🌪️", scene: "大地震のあと、道に倒れた電柱と、毛布をかぶって避難所へ歩く人たち。", flow: ["悪い星のめぐり", "大きな災害・惨事"], parts: [["dis", "悪い"], ["aster", "星"]], fam: ["asterisk（＊印）", "astronaut（宇宙飛行士）"], pair: "accident は「事故」、disaster は「多くの人がこまる大災害」。" },
    "emission": { hint: "e（外へ）＋mit（送る）", core: "中から『外へ出されるもの』。車や工場から出る二酸化炭素など。", tip: "動詞は emit（出す）。submit と同じ mit（送る）。", pic: "💨", scene: "工場のえんとつから、灰色のけむりがもくもくと空へ上がっていく。", flow: ["外へ送り出す", "ガスの排出", "排出量"], parts: [["e", "外へ（ex）"], ["miss", "送る"], ["ion", "こと"]], fam: ["emit（出す）", "mission（任務）"], pair: "emission は「排出」、mission は「任務」。" },
    "evidence": { hint: "vid は『見る』。目に見えるもの", core: "『目に見える、はっきりしたしるし』。男が建物にいたと示すものは見つからなかった。", tip: "e（外へ）＋vid（見る）。video（ビデオ）と同じ vid。", pic: "👣", scene: "事件の部屋で、警察官がピンセットで床の髪の毛を拾い、ふくろに入れる。", flow: ["はっきり見えるもの", "証拠"], parts: [["e", "外へ（ex）"], ["vid", "見る"], ["ence", "こと"]], fam: ["evident（明らかな）", "video（ビデオ）"], pair: "proof は「決定的な証明」、evidence は「判断の材料になる証拠」。" },
    "consumer": { hint: "スーパーで商品を買って使う人", core: "ものやサービスを『買って使いきる人』。環境によい商品を選ぶ人が増えた。", tip: "consume（使いきる）＋er（人）。反対は producer（生産者）。", pic: "🛒", scene: "買い物客が卵のパックを裏返し、『エコ』のマークを確かめてかごに入れる。", flow: ["使いきる人", "消費者"], fam: ["consume（消費する）", "consumption（消費）"], pair: "consumer は「消費者」、customer は「店のお客」。" },
    "factor": { hint: "結果を生み出す、いくつかの『もと』の一つ", core: "結果を『作り出すもとの一つ』。スマホを選ぶとき、値段が大きな決め手になる。", tip: "fac（作る）。factory（工場）と同じ仲間。", scene: "スマホ売り場で、値段・色・カメラの性能を紙に書き出し、一つずつ比べる。", flow: ["結果を作るもと", "要因・要素"], parts: [["fact", "作る"], ["or", "もの"]], fam: ["factory（工場）"], pair: "cause は「原因」、factor は「いくつかある要因の一つ」。" },
    "fee": { hint: "博物館の入り口や、手続きのときに払うお金", core: "サービスや手続きに『払うお金』。入館料・授業料など。", tip: "entrance fee（入場料）、school fee（授業料）のセットで覚える。", pic: "💴", scene: "美術館のチケット売り場で、大人がトレイに500円玉を一枚置く。", flow: ["サービスに払うお金", "料金・手数料"], pair: "fee は「入場料・手数料」、fare は「乗り物の運賃」。" },
    "fuel": { hint: "車やストーブに入れて、燃やすもの", core: "『燃やして力を出すもの』。ガソリンや灯油など。値上がりして車に乗る人が減った。", tip: "fossil fuel（化石燃料）のセットで覚える。", pic: "⛽", scene: "ガソリンスタンドで、電光板の値段が上がっているのを見て、ドライバーがため息をつく。", flow: ["燃やして力を出すもの", "燃料"], pair: "fuel は「燃料」、energy は「エネルギー」全般。" },
    "function": { hint: "パソコンの F キー（ファンクションキー）", core: "ものが持っている『はたらき・役わり』。歩いた歩数を数えてくれる時計のはたらき。", tip: "動詞でも使い『はたらく』。ファンクションキー＝特別なはたらきのキー。", pic: "⚙️", scene: "新しい腕時計を見ると、歩くたびに画面の数字が1つずつ増えていく。", flow: ["はたらき", "機能・役割", "（動）機能する"], pair: "function は「はたらき」、feature は「目立つ特徴」。" },
    "generation": { hint: "『昭和生まれ』『平成生まれ』のような人のまとまり", core: "『同じころに生まれた人たち』のまとまり。未来の人たちも自然を楽しめるように。", tip: "generate（生み出す）と同じ gen（生まれる）。", pic: "👶👦👴", scene: "同じ食卓で、祖父はラジオ、父はテレビ、孫はスマホでそれぞれニュースを見ている。", flow: ["生まれること", "同じころ生まれた人々", "世代"], parts: [["gener", "生む"], ["ation", "こと"]], fam: ["generate（生み出す）", "gene（遺伝子）"], pair: "generation は「世代」、age は「年齢・時代」。" },
    "currency": { hint: "current（流れ）が入っている", core: "世の中を『流れて回るお金』。旅行の前に、その国のお金に両替する。", tip: "current（流れ）と同じ語源。cur は『走る・流れる』。", pic: "💱", scene: "空港の両替所で、千円札をわたすと、見なれない色の外国のお札が返ってくる。", flow: ["流れて回るもの", "通貨"], parts: [["curr", "流れる・走る"], ["ency", "こと"]], fam: ["current（流れ・現在の）"], pair: "currency は「通貨」、cash は「現金」。" },
    "incident": { hint: "ふと起きてしまった、あるできごと", core: "ふと『降りかかってきたできごと』。学校で起きた（よくない）こと。", tip: "in（上に）＋cid（落ちる）。accident（事故）と同じ cid。", scene: "休み時間のろうかで、ボールが窓に当たってガラスが割れ、先生たちが集まってくる。", flow: ["降りかかってくること", "出来事", "事件"], parts: [["in", "上に"], ["cid", "落ちる"], ["ent", "～なこと"]], fam: ["accident（事故）"], pair: "accident は「思わぬ事故」、incident は「（よくない）出来事・事件」。" },
    "deadline": { hint: "この線をこえたらアウト、という日時", core: "『これをこえたらもうダメな線』。スピーチコンテストに申しこめる最後の日。", tip: "dead（死んだ）＋line（線）＝こえたらアウトの線。", pic: "⏰", scene: "夜11時59分、パソコンの前で、申しこみボタンを急いでクリックする。", flow: ["こえたらアウトの線", "締め切り"], parts: [["dead", "死んだ"], ["line", "線"]], pair: "deadline は「締め切り」、limit は「限度・制限」。" },
    "destination": { hint: "旅のゴール。飛行機の画面に表示される", core: "旅や荷物が『向かうと決まった場所』。ハワイは今も人気の旅先。", tip: "destiny（運命＝決まった先）と同じ語源。", pic: "📍", scene: "空港の電光掲示板に、『HONOLULU』の文字と出発時刻が光っている。", flow: ["向かうと決めた所", "目的地・行き先"], fam: ["destiny（運命）"], pair: "destination は「行き先」、departure は「出発」。" },
    "insurance": { hint: "sure（確かな）が入っている", core: "もしもに備えて『安心を確かにしておくしくみ』。外国で病気になったときに備える。", tip: "動詞 insure は sure（確か）から。ensure と仲間。", pic: "☂️", scene: "旅先の病院で、受付に保険のカードを見せると、払うお金が0円になる。", flow: ["安心を確かにする", "保険"], fam: ["insure（保険をかける）", "ensure（確実にする）"], pair: "insurance は「保険」、assurance は「保証・自信」。" },
    "investment": { hint: "お金や時間を今つかって、将来の得を待つ", core: "今お金や時間を『入れておいて、あとでもどってくるのを待つ』。よい靴は健康のためのよい使い道。", tip: "動詞は invest、する人は investor（投資家）。", pic: "🌱", scene: "高いランニングシューズを買い、毎朝走るうちに、体の調子がどんどんよくなる。", flow: ["中に入れておく", "お金・時間の投資"], fam: ["invest（投資する）", "investor（投資家）"], pair: "investment は「投資」、savings は「貯金」。" },
    "laboratory": { hint: "labor（働く）が入っている。略すと lab", core: "実験や研究を『する（働く）部屋』。大学で植物の実験をする所。", tip: "labor（労働）と同じ仲間で『働く場所』。略して lab（ラボ）。", pic: "🥼", scene: "白衣の学生たちが、ガラスの容器に入った植物に光を当て、毎日長さを測っている。", flow: ["働く所", "研究所・実験室"], parts: [["labor", "働く"], ["atory", "場所"]], fam: ["labor（労働）", "lab（ラボ）"], pair: "laboratory は「実験室」、lavatory は「トイレ」。" },
    "landscape": { hint: "land（土地）が入っている", core: "目の前に広がる『土地全体のながめ』。秋の山のながめ。", tip: "land（土地）＋scape（ようす）。スマホの横向き画面も landscape。", pic: "🏞️", scene: "紅葉した山々が重なり、その間を白い川がくねくねと流れているのを丘から見下ろす。", flow: ["土地全体のながめ", "風景・景色"], parts: [["land", "土地"], ["scape", "ようす"]], fam: ["seascape（海の景色）"], pair: "view は「見える景色」全般、landscape は「土地の広いながめ」。" },
    "literature": { hint: "letter（文字）の仲間", core: "『文字で書かれた作品』、とくに小説や詩。大学で英語の作品を学んだ。", tip: "ラテン語 littera（文字）から。letter と同じ仲間。", pic: "📖", scene: "大学の図書館で、古い英語の詩集と小説が天井まで棚にぎっしり並んでいる。", flow: ["文字で書いたもの", "文学"], fam: ["letter（文字）", "literal（文字どおりの）"], pair: "literature は「文学」、literacy は「読み書きの力」。" },
    "mammal": { hint: "もとは mamma（おっぱい）という語", core: "『お乳で子を育てる動物』。クジラは魚に見えるが、空気を吸い、子に乳をあげる。", tip: "ラテン語 mamma（乳房）から。『ママ』と音が似ている。", pic: "🐋", scene: "水族館で、クジラが水面に上がって潮をふき、子クジラにお乳を飲ませている。", flow: ["乳で子を育てる", "哺乳動物"], pair: "mammal は「哺乳類」、reptile は「は虫類」。" },
    "expense": { hint: "家賃や食べ物の代など、出ていくお金", core: "『外へ出ていくお金』。都会では家賃や食べ物にお金がかかる。", tip: "ex（外へ）＋pense（はかって払う）。expensive（高い）と同じ仲間。", pic: "🧾", scene: "月末、家計簿に家賃・食費・電気代と書き、合計の多さに目を丸くする。", flow: ["はかって払う", "費用・出費"], parts: [["ex", "外へ"], ["pense", "はかる・払う"]], fam: ["expensive（高価な）", "spend（使う）"], pair: "cost は「かかる費用」、expense は「出ていくお金・出費」。" },
    "minister": { hint: "minor（より小さい）がもと。上の人に仕える人", core: "もとは国に『仕える人』。今は政府の大きな仕事をまかされた人。prime minister＝総理大臣。", tip: "ラテン語 minister（召し使い）。minor・minus（より小さい）と同じ仲間。", pic: "🏛️", scene: "国会の記者会見で、大臣がマイクの前に立ち、新しい教育の計画を発表する。", flow: ["仕える人", "政府の大臣"], fam: ["ministry（～省）", "minor（小さいほうの）"], pair: "minister は「大臣」、mayor は「市長」。" },
    "obstacle": { hint: "道の前に立ちはだかって、進めなくするもの", core: "目の前に『立ちふさがるもの』。お金がないことが、花屋を開く一番のかべだった。", tip: "ob（前に）＋sta（立つ）。障害物競走は obstacle race。", pic: "🚧", scene: "運動会の障害物競走で、子どもたちが網の下をくぐり、平均台をわたっていく。", flow: ["前に立ちふさがるもの", "障害（物）・壁"], parts: [["ob", "前に"], ["sta", "立つ"]], pair: "problem は「問題」、obstacle は「行く手をはばむもの」。" },
    "outcome": { hint: "最後に『外へ出てくる』もの", core: "最後に『外へ出てくるもの』。選挙が最後にどうなるか、だれにもわからなかった。", tip: "out（外へ）＋come（来る）＝出てくる。result とほぼ同じ。", scene: "開票速報の夜、テレビの前で家族が息をのみ、最後の数字が出るのを待っている。", flow: ["最後に出てくるもの", "結果"], parts: [["out", "外へ"], ["come", "来る"]], pair: "result とほぼ同じ。outcome は「話し合い・選挙のなりゆき」に多い。" },
    "permission": { hint: "『〜してもいいよ』と言ってもらうこと", core: "『通ってもいいと送り出すこと』。親が『行っていいよ』と言ってくれること。", tip: "動詞は permit。per（通して）＋mit（送る）。", pic: "🆗", scene: "夕食後、旅行の申込書を母の前に置き、サインしてもらうのをどきどきして待つ。", flow: ["通ってよいと送り出す", "許可"], parts: [["per", "通して"], ["miss", "送る"], ["ion", "こと"]], fam: ["permit（許す）", "submit（提出する）"], pair: "permission は「許可」、admission は「入場」。" },
    "phenomenon": { hint: "phen は『現れる・見える』", core: "目の前に『あらわれて見えるできごと』。オーロラのように自然の中で起きるもの。複数形 phenomena。", tip: "ギリシャ語 phainein（見せる）から。fantasy（空想）と同じ仲間。", pic: "🌌", scene: "北の国の夜空に、緑色の光のカーテンがゆらゆらとゆれている。", flow: ["目の前に現れたもの", "（自然の）現象"], fam: ["fantasy（空想）"], pair: "phenomenon の複数形は phenomena。event は「行事・出来事」。" },
    "policy": { hint: "選挙のとき、政党がかかげる『これからこう進めます』", core: "国や会社が『こうすると決めたやり方』。会議中はスマホを使わない、という会社の決まり。", tip: "ギリシャ語 polis（都市）から。politics・police と同じ仲間。", scene: "社長が会議室に『会議中スマホ禁止』と書いた紙をはり、全員に向かって話す。", flow: ["都市の治め方", "国の政策", "会社の方針"], fam: ["politics（政治）", "police（警察）"], pair: "policy は「方針・政策」、politics は「政治」。" },
    "nutrition": { hint: "体を育てるために、食べ物からとるもの", core: "体を『育てて養うもの』。育ちざかりの子どもにとってとくに大事。", tip: "nutri（養う）。nurse（世話をする人）と同じ仲間。", pic: "🥗", scene: "給食室の黒板に、今日の献立とビタミン・カルシウムの量が書いてある。", flow: ["体を養うもの", "栄養（をとること）"], fam: ["nutrient（栄養素）", "nurse（看護師）"], pair: "nutrition は「栄養」、nature は「自然」。" },
    "poverty": { hint: "毎日のごはんにもこまる家族を、支援団体が助ける", core: "お金や物が足りない『まずしい状態』。食べ物が十分にない家族を助ける。", tip: "poor（まずしい）の名詞。ラテン語 pauper（まずしい）から。", scene: "穴のあいたくつをはいた子が、給食だけが一日の食事だと小さな声で言う。", flow: ["まずしいこと", "貧困"], fam: ["poor（まずしい）"], pair: "poverty は「貧困」、property は「財産」。つづりに注意。" },
    "priority": { hint: "新しい市長が、まず一番に手をつけると決めたこと", core: "ほかより『先にすること』。新しい市長にとって、町を安全にするのが一番先。", tip: "prior（先の）＋ity。カタカナでプライオリティ。", scene: "冷蔵庫にはったやることリストの一番上に、赤い星が3つついている。", flow: ["ほかより先", "優先（事項）"], parts: [["prior", "先の"], ["ity", "こと"]], fam: ["prior（前の）"], pair: "priority は「優先」、majority は「大多数」。" },
    "profit": { hint: "売り上げから、かかったお金を引いて残るもの", core: "商売をして『手元に残るもうけ』。ネットで売って、大きなもうけを出した。", tip: "ラテン語 proficere（前へ進む）から。反対は loss（損失）。", pic: "💰", scene: "ネットショップの社長が、売上の画面を見て『今月もプラスだ』とガッツポーズ。", flow: ["前へ進む・役に立つ", "利益・もうけ"], fam: ["profitable（もうかる）"], pair: "profit は「もうけ」、benefit は「利益・恩恵」全般。" },
    "proportion": { hint: "portion（部分・取り分）が入っている", core: "全体の中の『部分の大きさ』。生徒の多くが歩きか自転車で通っている。", tip: "pro（～に応じて）＋portion（部分）。ポーション（一人分）と同じ。", pic: "🍰", scene: "校門の前で、生徒の10人中8人が歩きか自転車でやって来る。", flow: ["全体の中の部分", "割合・比率"], parts: [["pro", "～に応じて"], ["portion", "部分"]], fam: ["portion（一部・一人前）"], pair: "proportion は「割合」、percentage は「百分率」。" },
    "proposal": { hint: "プロポーズは結婚の『申しこみ』", core: "『前に出して置く考え』。駅までの道に花を植えようと言い出す。", tip: "pro（前に）＋pose（置く）。動詞 propose（提案する・プロポーズする）。", scene: "ホームルームで、生徒が手をあげ『駅までの道に花を植えませんか』と言う。", flow: ["前に出して置く", "提案", "結婚の申しこみ"], parts: [["pro", "前に"], ["pos", "置く"], ["al", "こと"]], fam: ["propose（提案する）", "purpose（目的）"], pair: "suggestion は「軽い提案」、proposal は「正式な提案」。" },
    "quantity": { hint: "quality とつづりが似ている。工場が毎日作る紙の…", core: "どれだけあるかの『多さ・かさ』。工場は毎日たくさんの紙を作る。", tip: "quality（質）と quantity（量）。n があるほうが『量』。", scene: "米袋が倉庫の天井までぎっしり積まれ、トラックが次々と運び出していく。", flow: ["どれだけあるか", "量"], pair: "quantity は「量」、quality は「質」。n があるほうが量。" },
    "reputation": { hint: "まわりの人があなたを『どう思っているか』", core: "まわりの人が『くり返し考えて持っている見方』。スタッフと朝食で知られたホテル。", tip: "re（くり返し）＋pute（考える）。computer（計算する機械）と同じ pute。", pic: "⭐", scene: "口コミサイトで、そのホテルに『スタッフが親切』という★5つの声がずらりと並ぶ。", flow: ["くり返し考えた見方", "評判・名声"], parts: [["re", "くり返し"], ["put", "考える"], ["ation", "こと"]], fam: ["computer（計算する機械）"], pair: "reputation は「評判」、popularity は「人気」。" },
    "occupation": { hint: "書類で、名前・年齢の次によく書く欄", core: "毎日の時間を『占めているもの』＝仕事。occupy（占める）の名詞。", tip: "occupy（占める）から。一日の時間を占めるのが仕事。", pic: "💼", scene: "入国カードの空欄に、旅行者が『会社員』と英語で書きこむ。", flow: ["時間を占めるもの", "職業"], fam: ["occupy（占める）"], pair: "occupation は書類で使うかたい「職業」、job はふだんの「仕事」。" },
    "prescription": { hint: "病院でもらって、薬局に持っていく紙", core: "医者が『前もって書いてくれる薬の指示』。この薬を買うには医者の紙が必要。", tip: "pre（前に）＋script（書く）。script（台本）と同じ。", pic: "💊📄", scene: "診察のあと、医者がパソコンに薬の名前を打ち、プリンターから紙が出てくる。", flow: ["前もって書いたもの", "処方箋"], parts: [["pre", "前に"], ["script", "書く"], ["ion", "こと"]], fam: ["script（台本）", "describe（描写する）"], pair: "prescription は「処方箋」、description は「説明・描写」。" },
    "shortage": { hint: "short（短い）が入っている", core: "必要な量に『とどかない状態』。田舎の病院では医者が足りない。", tip: "short（短い・足りない）＋age。be short of ～（～が足りない）。", scene: "田舎の病院の待合室が人でいっぱいで、医者は一人しかいない。", flow: ["足りないこと", "不足"], parts: [["short", "足りない"], ["age", "状態"]], pair: "shortage は「不足」、lack も「不足」だが lack は動詞にもなる。" },
    "refund": { hint: "fund（お金・資金）が入っている", core: "払ったお金が『もとへもどってくる』こと。満足できなければ全額返してもらえる。", tip: "re（もとへ）＋fund。ラテン語 refundere（注ぎ返す）から。", pic: "💴↩️", scene: "サイズの合わないくつをレジに返すと、店員さんが代金をそのまま手にもどしてくれる。", flow: ["注ぎ返す", "払い戻し"], parts: [["re", "もとへ"], ["fund", "注ぐ"]], pair: "refund は「払い戻し」、discount は「値引き」。" },
    "strategy": { hint: "将棋の名人が、最初の一手より前に考えておく大きな道すじ", core: "勝つための『大きな作戦』。決勝の前に、コーチが新しい作戦を説明する。", tip: "ギリシャ語で『軍を導くこと』から。ストラテジーゲーム。", pic: "♟️", scene: "決勝の前夜、コーチがホワイトボードに選手の動きを矢印でいっぱい書きこむ。", flow: ["軍を導くこと", "戦略・作戦"], pair: "plan は「計画」全般、strategy は「勝つための大きな作戦」。" },
    "survey": { hint: "上から全体を見わたすイメージ", core: "全体を『上から見わたして調べる』。たくさんの人に聞いて、全体のようすを見る。", tip: "sur（上から）＋vey（見る）。surface（表面）の sur と同じ。", scene: "駅前で、バインダーを持った人が通る人に『朝は何時に起きますか』と聞いて回る。", flow: ["上から見わたす", "全体の調査", "アンケート"], parts: [["sur", "上から"], ["vey", "見る"]], fam: ["surface（表面）"], pair: "survey は「多くの人に聞く調査」、research は「研究」。" },
    "symptom": { hint: "病気のとき、体に出てくるサイン", core: "病気が『体の表に出したサイン』。熱やせき。悪いことの前ぶれにも使う。", tip: "ギリシャ語で『いっしょに起こるもの』。sym（いっしょ）は symphony と同じ。", pic: "🤒", scene: "朝起きると、のどがいがいがし、おでこにさわると熱い。", flow: ["いっしょに起こるもの", "病気の症状", "悪いことの兆し"], fam: ["symphony（交響曲）"], pair: "symptom は「症状」、disease は「病気そのもの」。" },
    "tendency": { hint: "tend（向かう）が入っている", core: "ある方向へ『向かいやすいこと』。若者はテレビよりネットに時間を使いがち。", tip: "動詞 tend to ～（～しがちだ）。tend＝のびて向かう。", scene: "夕食後、テレビはついているのに、家族全員がそれぞれのスマホを見ている。", flow: ["ある方向へ向かう", "傾向・～しがち"], parts: [["tend", "向かう"], ["ency", "こと"]], fam: ["tend（～しがちだ）"], pair: "tendency は「人の傾向」、trend は「世の中の流行」。" },
    "threat": { hint: "『〜するぞ』とおどすもの", core: "せまってきて『害をあたえるおそれのあるもの』。海面の上昇が小さな島国をおびやかす。", tip: "動詞は threaten（おどす）。読み方は『スレット』。", scene: "小さな島の海辺で、満潮のたびに波が家の庭先まで来て、住民が不安そうに見ている。", flow: ["おどすもの", "危険がせまるおそれ", "脅威"], fam: ["threaten（おどす・おびやかす）"], pair: "danger は「危険そのもの」、threat は「害をあたえるおそれ」。" },
    "satellite": { hint: "地球のまわりを回る、宇宙の機械", core: "大きなもののまわりを『つき従って回るもの』。雲の写真を送ってくる気象衛星。", tip: "ラテン語で『おともの人』。衛星放送＝サテライト放送。", pic: "🛰️", scene: "夜空を、星のような小さな光が一つ、音もなくすーっと横切っていく。", flow: ["おともの人", "まわりを回る衛星", "人工衛星"], pair: "satellite は「衛星」、planet は「惑星」。" },
    "welfare": { hint: "お年寄りや困っている人の暮らしを支えるしくみ", core: "人が『よく暮らしていけること』と、それを支えるしくみ。お年寄りへの支え。", tip: "well（よく）＋fare（やっていく）。farewell（さようなら）と同じ fare。", scene: "介護の人が毎朝ひとり暮らしのおばあさんの家を訪れ、薬と食事をチェックする。", flow: ["よくやっていくこと", "幸福", "社会の福祉"], parts: [["wel", "よく（well）"], ["fare", "やっていく"]], fam: ["farewell（別れ）"], pair: "welfare は「福祉」、warfare は「戦争」。つづりに注意。" },
    "scholarship": { hint: "scholar（学者・学ぶ人）が入っている", core: "学ぶ人を『お金で助けるしくみ』。カナダの大学で学べるようにしてくれた。", tip: "scholar（学ぶ人）＋ship。school と同じ仲間。", pic: "🎓", scene: "合格通知の封筒に『学費は全額こちらで払います』と書かれた紙が入っていた。", flow: ["学ぶ人を支えるもの", "奨学金"], parts: [["scholar", "学者・学ぶ人"], ["ship", "～の身分"]], fam: ["scholar（学者）", "school（学校）"], pair: "scholarship は「奨学金」、fee は「料金」。" },
    "economy": { hint: "エコノミークラス（飛行機の安い席）", core: "お金とものの『やりくり全体』。観光がこの島のやりくりを支えている。", tip: "ギリシャ語で『家のやりくり』。economical＝節約できる。", pic: "💹", scene: "観光客で港がにぎわい、土産物屋もホテルも魚市場も、島じゅうでお金が回っている。", flow: ["家のやりくり", "国・地域の経済", "節約"], fam: ["economic（経済の）", "economical（節約になる）"], pair: "economic は「経済の」、economical は「安上がりな」。" },

    // ===== 形容詞 =====
    "accurate": { hint: "ずれがなく、的にぴたりと当たる", core: "細かいところまで『気をつけて、まちがいがない』。天気予報がぴたりと当たるようになった。", tip: "ac（～に）＋cur（注意）。curious（好奇心がある）と同じ cur。", pic: "🎯", scene: "ダーツの矢が3本とも、まん中の赤い点に刺さっている。", flow: ["注意してまちがいがない", "情報・予報が正確な"], parts: [["ac", "～に（ad）"], ["cur", "注意"], ["ate", "～した"]], fam: ["accuracy（正確さ）", "curious（好奇心がある）"], pair: "accurate は「事実にぴったり」、exact は「ぴったり一致した」。" },
    "adequate": { hint: "equal（等しい）の仲間が入っている", core: "必要な量に『ちょうど等しい』。テストの時期は、必要なだけの睡眠をとれていない。", tip: "ad（～に）＋equ（等しい）。equal と同じ equ。", scene: "テスト前夜、時計を見ると夜中の3時。今夜も睡眠は足りそうにない。", flow: ["必要に等しい", "量が十分な", "適切な"], parts: [["ad", "～に"], ["equ", "等しい"], ["ate", "～した"]], fam: ["equal（等しい）"], pair: "enough は「足りる」、adequate は「必要を満たす（が最高ではない）」。" },
    "abundant": { hint: "波があふれるように、たっぷりある", core: "『あふれるほど多い』。雨がたっぷり降るので、米作りにぴったり。", tip: "ab（～から）＋und（波）＝波があふれ出る。", scene: "梅雨の田んぼに雨がたっぷり降り、あぜ道のみぞから水があふれ出ている。", flow: ["波があふれ出る", "たっぷりある・豊富な"], parts: [["ab", "～から"], ["und", "波"], ["ant", "～な"]], fam: ["abundance（豊富）"], pair: "abundant は「あふれるほど多い」、enough は「足りる」。" },
    "artificial": { hint: "art（技）が入っている。森ではなく工場生まれ", core: "自然ではなく『人の技で作った』。本物の果物ではない着色料は入っていない。", tip: "art（技）＋fic（作る）。AI＝artificial intelligence。", scene: "部屋のすみの観葉植物にさわると、葉っぱがつるつるのプラスチックだった。", flow: ["人の技で作った", "人工の・不自然な"], parts: [["art", "技"], ["fic", "作る"], ["ial", "～の"]], fam: ["art（芸術・技術）", "artist（芸術家）"], pair: "artificial は「人工の」、natural は「自然の」で反対。" },
    "capable": { hint: "cap は『つかむ・入れる』", core: "力を『中に持っていて、できる』。チームの声をよく聞く、たよれるリーダー。be capable of ～ing。", tip: "capacity（容量）と同じ cap。can の気持ちで覚える。", pic: "💪", scene: "新しい部長は、会議でみんなの意見をメモし、問題をあっという間に解決していく。", flow: ["中に力を持つ", "～できる", "有能な"], parts: [["cap", "つかむ・入れる"], ["able", "できる"]], fam: ["capacity（容量・能力）", "capability（能力）"], pair: "able は「できる」、capable は「力があって有能な」。be capable of ～ing。" },
    "considerable": { hint: "consider（よく考える）が入っている", core: "『考えに入れなければならないほど大きい』。橋づくりには、無視できないほどのお金と時間がかかる。", tip: "consider（考える）＋able＝考えに入れるほどの。", scene: "橋の工事の見積書をめくると、数字のゼロがずらりと並んでいる。", flow: ["考えに入れるほど", "かなりの・相当な"], parts: [["consider", "考える"], ["able", "できる"]], fam: ["considerate（思いやりのある）"], pair: "considerable は「かなりの」、considerate は「思いやりのある」。" },
    "crucial": { hint: "ラテン語 crux（十字）から。道が交わる地点", core: "成功か失敗かの『分かれ道になるほど大事』。暑い日の練習で、水は勝負を分ける。", tip: "crux（十字）＝道の交わる所。そこで行き先が決まる。", scene: "炎天下の練習中、水を飲んだ選手と飲まなかった選手で、後半の走りがまるでちがう。", flow: ["十字＝分かれ道", "勝負を分ける", "きわめて重要な"], fam: ["crux（核心）"], pair: "important は「大切な」、crucial は「結果を左右するほど大切な」。" },
    "affordable": { hint: "can't afford（お金の余裕がない）の afford", core: "お金の『余裕があって払える』くらいの。若い家族でも住める家。", tip: "afford（～する余裕がある）＋able（できる）。", pic: "🏷️", scene: "若い夫婦が不動産屋のチラシを見て、『この家賃なら払える』と顔を見合わせる。", flow: ["余裕がある", "（値段が）手ごろな"], parts: [["afford", "余裕がある"], ["able", "できる"]], pair: "cheap は「安っぽい」感じもある。affordable は「無理なく買える」。" },
    "domestic": { hint: "dom は『家』", core: "『家の中の』。家の中→家庭の、国を一つの家と見て→国内の。domestic flight＝国内線。", tip: "ラテン語 domus（家）から。dome（ドーム）と同じ仲間。", pic: "🏠", scene: "空港の案内板が『国際線』と『国内線』に分かれ、夏休みの家族が国内線へ流れていく。", flow: ["家の中の", "家庭の", "国内の"], fam: ["dome（ドーム）", "domesticate（飼いならす）"], pair: "domestic は「国内の」、international は「国際の」。" },
    "humid": { hint: "日本の夏の、むしむし・ベタベタした空気", core: "空気が『水気をたっぷりふくんだ』。東京の夏は暑くてむしむしする。", tip: "名詞は humidity。加湿器は humidifier。", pic: "💦", scene: "梅雨の朝、窓を開けると、むわっとした空気が顔にはりつき、シャツが肌にくっつく。", flow: ["水気をふくんだ", "湿度の高い"], fam: ["humidity（湿度）", "humidifier（加湿器）"], pair: "humid は「じめじめ」、dry は「乾燥した」。wet は「ぬれた」。" },
    "extinct": { hint: "火が消えるように、もう二度と見られない", core: "火が『消えてしまった』ように、その種類が全部いなくなった。恐竜のように。", tip: "ex（外へ）＋tinct（消す）。extinguisher（消火器）と同じ仲間。", pic: "🦕", scene: "博物館で、子どもが恐竜の骨の前に立ち、『もうどこにもいないの？』と聞く。", flow: ["火が消えた", "種が絶滅した", "火山が活動をやめた"], parts: [["ex", "外へ"], ["tinct", "消す"]], fam: ["extinction（絶滅）", "extinguisher（消火器）"], pair: "extinct は「絶滅した」、endangered は「絶滅のおそれがある」。" },
    "flexible": { hint: "flex は『曲げる』", core: "『曲げられる、しなやか』。体にも予定にも使う。働く時間を自由に動かせる。", tip: "flex（曲げる）＋ible。フレックスタイムと同じ。", pic: "🤸", scene: "ヨガの先生が、足を頭の上までくにゃりと曲げて、にっこり笑う。", flow: ["曲げられる", "体が柔軟な", "予定に融通がきく"], parts: [["flex", "曲げる"], ["ible", "できる"]], fam: ["reflect（反射する）"], pair: "flexible は「しなやか・融通がきく」、strict は「厳しい」。" },
    "numerous": { hint: "number（数）が入っている", core: "『数えきれないほど数が多い』。歌手が10年でたくさんの賞をとった。", tip: "number（数）と同じ仲間。numerous awards＝数々の賞。", scene: "歌手の部屋の棚に、トロフィーと賞状がすき間なくずらりと並んでいる。", flow: ["数が多い", "非常に多くの"], parts: [["numer", "数"], ["ous", "～が多い"]], fam: ["number（数）", "numeral（数字）"], pair: "numerous は数えられる名詞に使う。much は数えられない名詞。" },
    "genuine": { hint: "美術館の古い絵。にせものかどうか、専門家が調べた結果", core: "『作りものではなく、そのもの』。その絵は、言われた画家が本当にかいたもの。気持ちにも使う。", tip: "genuine leather（本革）のように品物によく使う。fake の反対。", scene: "鑑定士がルーペで古い絵の右下のサインを確かめ、『まちがいありません』とうなずく。", flow: ["作りものではない", "本物の", "心からの"], pair: "genuine は「本物の」、fake は「にせの」で反対。" },
    "permanent": { hint: "パーマ（パーマネント）はずっと続く髪型", core: "『ずっと終わりなく続く』。アルバイトではなく、ずっと続けられる仕事についた。", tip: "per（通して）＋manent（とどまる）。パーマは permanent wave の略。", pic: "♾️", scene: "アルバイトの青年が、店長から新しい名札と『正社員』と書かれた書類を受け取る。", flow: ["ずっととどまる", "永久的な", "常勤の"], parts: [["per", "通して"], ["man", "とどまる"], ["ent", "～な"]], fam: ["remain（とどまる）"], pair: "permanent は「ずっと続く」、temporary は「一時的な」で反対。" },
    "immediate": { hint: "medi は『間』。間に何もない", core: "『間に何もはさまない』→すぐの。洪水のあと、政府がすぐに手を打った。", tip: "im（ない）＋medi（間）。副詞は immediately（すぐに）。", pic: "⚡", scene: "川があふれたニュースのすぐあと、ヘリコプターが飛び立ち、救助隊が出発する。", flow: ["間に何もない", "即座の", "すぐ近くの"], parts: [["im", "ない（in）"], ["medi", "間"], ["ate", "～の"]], fam: ["immediately（すぐに）", "medium（中間）"], pair: "immediate は「すぐの」、urgent は「急を要する」。" },
    "sensitive": { hint: "sense（感覚・センス）が入っている", core: "『感じやすい』。刺激をすぐ感じるはだ。心が傷つきやすいことにも使う。", tip: "sense（感じる）から。センシティブな話題＝気をつけてあつかう話題。", scene: "新しい石けんで顔を洗ったら、ほおがすぐに赤くなり、ちくちくしてきた。", flow: ["感じやすい", "肌が敏感な", "心が繊細な・扱いに注意"], parts: [["sens", "感じる"], ["itive", "～しやすい"]], fam: ["sense（感覚）", "sensible（分別のある）"], pair: "sensitive は「敏感な」、sensible は「分別のある」。まぎらわしい。" },
    "initial": { hint: "名前の頭文字『イニシャル』", core: "『始まりの』。最初は車で行く予定だったが、電車にした。", tip: "イニシャル＝名前の始まりの文字。initiative（始める力）も仲間。", scene: "旅行の計画表の一行目に『車で行く』と書いてあり、そこに線が引かれている。", flow: ["始まりの", "最初の", "頭文字"], fam: ["initiative（主導・率先）", "initially（最初は）"], pair: "initial は「最初の」、final は「最後の」で反対。" },
    "mental": { hint: "試合前に手がふるえる選手。必要なのは筋肉とは別の強さ", core: "『頭や気持ちの中の』。自然の中ですごすと、体にも頭や気持ちにもよい。", tip: "メンタルヘルス。反対は physical（体の）。", pic: "🧠", scene: "森の中を一時間歩くと、頭のもやもやが消え、気持ちがすーっと軽くなる。", flow: ["頭・心の", "精神の"], pair: "mental は「心の」、physical は「体の」で反対。" },
    "moderate": { hint: "mod は『はかる』。ほどよくはかった量", core: "『ほどほどにはかった』。はげしすぎない、歩くくらいの運動。", tip: "modify と同じ mod（はかる）。司会のモデレーターも同じ仲間。", pic: "🚶", scene: "朝の公園で、お年寄りが軽く汗をかくくらいのペースで、おしゃべりしながら歩く。", flow: ["はかって決めた", "ほどよい・適度な", "穏やかな"], fam: ["modest（控えめな）", "moderator（司会者）"], pair: "moderate は「ほどほどの」、extreme は「極端な」。" },
    "obvious": { hint: "道の真ん前にあるくらい、だれにでもわかる", core: "目の前の『道にあるように、すぐわかる』。顔を見れば、つかれているのがすぐわかった。", tip: "ob（前に）＋via（道）＝道の前にある。via（～経由で）と同じ。", scene: "長旅から帰った父の目は赤く、ソファに座るなり大きなあくびをした。", flow: ["道の前にある", "だれにでもわかる", "明らかな"], parts: [["ob", "前に"], ["vi", "道"], ["ous", "～な"]], fam: ["via（～経由で）", "previous（前の）"], pair: "clear も「明らか」。obvious は「言うまでもなくわかる」。" },
    "portable": { hint: "port は『運ぶ』", core: "『運べる』。ポケットに入るほど小さいスピーカー。", tip: "port（運ぶ）＋able（できる）。export（輸出）と同じ port。", pic: "📻", scene: "キャンプ場で、ポケットから小さなスピーカーを取り出し、川辺に置いて音楽を流す。", flow: ["運べる", "持ち運びできる"], parts: [["port", "運ぶ"], ["able", "できる"]], fam: ["export（輸出する）", "transport（輸送する）"], pair: "portable は「持ち運べる」、mobile は「動かせる・移動できる」。" },
    "precise": { hint: "余分なところを切りとって、ぴったり", core: "余分を『切りとって、ぴったり』。パンを何分焼くかを、ぴったり書いたレシピ。", tip: "pre（前で）＋cise（切る）。concise（簡潔な）も同じ cise。", pic: "📐", scene: "パン職人がタイマーを18分ちょうどに合わせ、生地を1グラム単位で量っている。", flow: ["前で切りそろえる", "ぴったり正確な", "精密な"], parts: [["pre", "前で"], ["cise", "切る"]], fam: ["precision（精密さ）", "concise（簡潔な）"], pair: "accurate は「事実と合う」、precise は「細かい所までぴったり」。" },
    "previous": { hint: "pre（前に）＋vi（道）", core: "『道の先を行った』→一つ前の。今年の売り上げは、その一つ前の年よりずっと多い。", tip: "pre（前に）＋vi（道）。obvious の via と同じ『道』。", pic: "⏪", scene: "カレンダーを一枚前にめくって、先月の予定を確かめる。", flow: ["道を先に行った", "一つ前の・以前の"], parts: [["pre", "前に"], ["vi", "道"], ["ous", "～の"]], fam: ["previously（以前に）", "obvious（明らかな）"], pair: "previous は「すぐ前の」、former は「元の・かつての」。" },
    "primary": { hint: "この活動で、ほかの何より先に目ざしていること", core: "『1番目に来る、いちばん大事な』。この活動のいちばんの目的は読書を楽しむこと。", tip: "prim（1番目）。prime minister（総理大臣）、primary school（小学校）。", scene: "読書会のポスターに、大きな字で『まずは本を楽しもう』と一つだけ書いてある。", flow: ["1番目の", "主要な・第一の", "初等の"], parts: [["prim", "1番目"], ["ary", "～の"]], fam: ["prime（最も重要な）", "primitive（原始的な）"], pair: "primary は「いちばん大事な」、secondary は「二番目の」。" },
    "rapid": { hint: "川の急流や、新幹線のスピードをイメージ", core: "『すばやく、どんどん』。町があっという間に大きくなって、渋滞が起きた。", tip: "ラテン語 rapidus（ひったくるように速い）から。", pic: "🚀", scene: "空き地だった駅前に、一年でビルが次々と建ち、道は車でぎっしりになった。", flow: ["ひったくるように速い", "急速な"], fam: ["rapidly（急速に）"], pair: "fast は「速い」全般、rapid は「変化・成長が急な」。" },
    "reasonable": { hint: "reason（理由・りくつ）が入っている", core: "『りくつに合う、ちょうどいい』。値段が高すぎず、りくつに合う→手ごろ。", tip: "reason（理由）＋able＝りくつに合う。", scene: "駅前のホテルのサイトで、部屋がきれいなのに一泊の値段を見て『安い！』と声が出る。", flow: ["りくつに合う", "値段が手ごろな", "妥当な"], parts: [["reason", "りくつ"], ["able", "できる"]], pair: "cheap は「安い」、reasonable は「値段に見合っていて手ごろ」。" },
    "reliable": { hint: "レポートに使うなら、ネットのうわさより図書館の本", core: "『たよることができる』。レポートには、たよれる情報源を使う。", tip: "rely on（～にたよる）＋able（できる）。", scene: "毎日同じ時刻にぴたりとホームに入ってくる電車を見て、駅員がうなずく。", flow: ["たよることができる", "信頼できる"], parts: [["reli", "たよる（rely）"], ["able", "できる"]], fam: ["rely（たよる）", "reliance（依存）"], pair: "reliable は「物・情報がたよれる」、trust は「人を信じる」。" },
    "rural": { hint: "若者が仕事を求めて都会へ出ていく、静かな地域", core: "『畑や野原が広がる』地域の。若者が仕事を求めて、そうした地域から大都市へ移る。", tip: "urban（都会の）とペアで覚える。ラテン語 rus（田園）から。", pic: "🌾", scene: "田んぼの向こうに山が見え、バス停の時刻表には1日3本しか書かれていない。", flow: ["田園の", "田舎の"], fam: ["rustic（素朴な）"], pair: "rural は「田舎の」、urban は「都会の」でペア。" },
    "severe": { hint: "冬の寒さ・痛み・罰などが『ひどい』ときに使う", core: "手かげんなく『きびしい』。ひどい冬の天気で飛行機が欠航。病気や問題が重いときにも。", tip: "severe weather（悪天候）、severe pain（はげしい痛み）のセットで。", pic: "🥶", scene: "大雪で空港が真っ白になり、電光掲示板に『欠航』の文字がずらりと並ぶ。", flow: ["手かげんなし", "天候が厳しい", "病気・問題が深刻な"], pair: "strict は「（人・規則が）厳しい」、severe は「（状態が）ひどい」。" },
    "significant": { hint: "sign（しるし）が入っている", core: "『しるしになるほど目立つ』。新しい薬が、患者の生活にはっきりした違いを生んだ。", tip: "sign（しるし）＋fic（作る）。signify（示す）と同じ仲間。", scene: "新薬を飲み始めた患者が、杖なしでスタスタ歩けるようになり、家族が驚く。", flow: ["しるしになるほど", "重要な", "量がかなりの"], parts: [["sign", "しるし"], ["ific", "作る"], ["ant", "～な"]], fam: ["signify（示す）", "signal（合図）"], pair: "important は「大切な」、significant は「目立つほど意味がある」。" },
    "sufficient": { hint: "必要なところまで、ちゃんと届いている", core: "必要な量に『下から満たして届いている』。全部の問題に答える時間が足りなかった。", tip: "suf（下から）＋fic（作る）。enough とほぼ同じ。反対は insufficient。", scene: "テスト終了のチャイムが鳴ったとき、答案の最後の三問がまだ白いままだった。", flow: ["下から満たす", "十分な"], parts: [["suf", "下から（sub）"], ["fic", "作る"], ["ient", "～な"]], fam: ["insufficient（不十分な）"], pair: "enough とほぼ同じ。sufficient のほうがかたい語。" },
    "temporary": { hint: "tempo（テンポ＝時間）が入っている", core: "『限られた時間だけの』。夏休みのあいだだけのホテルの仕事。反対は permanent。", tip: "tempor＝『時』。tempo（テンポ）と同じ仲間。", pic: "⏳", scene: "夏休みのあいだだけ、ホテルの名札をつけてベッドを整える大学生。", flow: ["限られた時の", "一時的な・仮の"], parts: [["tempor", "時"], ["ary", "～の"]], fam: ["tempo（テンポ）", "contemporary（現代の）"], pair: "temporary は「一時的な」、permanent は「永久的な」で反対。" },
    "urban": { hint: "人口が多く、電車と人がいつも行き交う地域", core: "『ビルが多い町の』。鳥がビルの多い地域でも暮らせるようになった。", tip: "rural（田舎の）とペアで覚える。ラテン語 urbs（都市）から。", pic: "🏙️", scene: "高いビルのすき間に、カラスがハンガーで巣を作り、下では車が行き交う。", flow: ["都市の", "都会の"], fam: ["suburban（郊外の）"], pair: "urban は「都会の」、rural は「田舎の」でペア。" },
    "vital": { hint: "vitamin（ビタミン）と同じ『命』の仲間", core: "『命にかかわるほど大事な』。ハチは果物の木が育つのに欠かせない役目をもつ。", tip: "vit（命）。vitamin、バイタルサイン（生きているしるし）。", pic: "❤️", scene: "果樹園で、ハチが花から花へ飛び回らなければ、秋にリンゴは一つも実らない。", flow: ["命の", "命にかかわるほど大事", "必要不可欠な"], parts: [["vit", "命"], ["al", "～の"]], fam: ["vitamin（ビタミン）", "vitality（活力）"], pair: "important は「大切な」、vital は「なくては生きられないほど大切な」。" },

    // ===== 副詞 =====
    "approximately": { hint: "proxim は『近い』", core: "正確な数に『近い』。東京からロンドンまで、14時間くらい。", tip: "ap（～へ）＋proxim（近い）。proximity（近さ）と同じ。", scene: "機内の画面に『ロンドンまで あと14時間ほど』と出て、地図の飛行機がゆっくり進む。", flow: ["近い", "正確な数に近い", "およそ"], parts: [["ap", "～へ（ad）"], ["proxim", "近い"]], fam: ["proximity（近さ）", "approximate（おおよその）"], pair: "about とほぼ同じ。approximately のほうがかたい。" },
    "eventually": { hint: "event（できごと）が入っている。いろいろあって…", core: "いろいろあって『最後には』。何時間も探して、やっと犬を見つけた。", tip: "event と同じ語源で『結果として出てくる』。『最後の結果としては』と覚える。", scene: "日がしずむまで公園を探し回り、最後にベンチの下で丸くなっている犬を見つけた。", flow: ["結果として出てくる", "最終的に・ついに"], fam: ["eventual（最終的な）"], pair: "finally は「とうとう」、eventually は「いろいろあって結局」。" },
    "merely": { hint: "たいしたものではない、と小ささを強めて言う", core: "『ほんのそれだけ』。賞は小さな賞状だけだったが、彼女はほこらしかった。", tip: "mere（ほんの）＋ly。only に近い。", scene: "表彰台でもらったのは、はがき大の紙一枚。それでも彼女は胸をはっている。", flow: ["ほんのそれだけ", "単に・ただ"], fam: ["mere（ほんの）"], pair: "only とほぼ同じ。merely は「たいしたことはない」感じが強い。" },
    "nevertheless": { hint: "never（決して～ない）の仲間が入った長い語", core: "前のことが『あっても少しも変わらず』。テストは難しかった。それでも多くが合格した。", tip: "never（決して～ない）＋the less（それだけ少なく）＝少しも減らない。", scene: "大雨で何人も転んだのに、選手たちはどろだらけのまま最後まで走りぬいた。", flow: ["少しも減らない", "それにもかかわらず"], parts: [["never", "決して～ない"], ["the", "それだけ"], ["less", "少なく"]], pair: "however は「しかし」、nevertheless は「それでもやはり」と強い。" },
    "rarely": { hint: "レアカードの『レア』の仲間", core: "『めずらしいくらいしか～しない』。父は忙しくて、いっしょに夕食を食べることがほとんどない。", tip: "レアカード＝なかなか出ないカード。否定の気持ちをふくむ語。", scene: "夕食の食卓に、父のいすだけがいつも空いていて、たまに座ると家族がびっくりする。", flow: ["めずらしい", "めったに～ない"], fam: ["rare（まれな）"], pair: "rarely は「めったに～ない」、often は「よく」。" },
    "roughly": { hint: "ラフなスケッチの『ラフ』", core: "細かくなく『ざっくりと』。町の人のだいたい半分が観光の仕事をしている。", tip: "ラフ（rough）なスケッチ＝ざっとかいた下書き。", scene: "広場の人だかりを見て、『だいたい半分は観光客だな』と手でざっくり分ける。", flow: ["ざっくりと", "おおよそ", "乱暴に"], fam: ["rough（ざらざらの・大まかな）"], pair: "roughly は「おおよそ」、exactly は「正確に」。" },
    "thoroughly": { hint: "through（通りぬけて）と同じ仲間", core: "『はしからはしまで通して、すみずみまで』。料理の前に野菜をすみずみまで洗う。", tip: "thorough は through の古い形。最初から最後まで通すイメージ。", pic: "🧽", scene: "ボウルの水の中で、キャベツの葉を一枚ずつはがし、すみずみまで指でこすり洗う。", flow: ["はしからはしまで通す", "徹底的に・すっかり"], fam: ["thorough（徹底的な）", "through（通りぬけて）"], pair: "thoroughly は「すみずみまで」、completely は「完全に」。" },
    "apparently": { hint: "appear（見える）の仲間", core: "『見たところ・聞いたところでは』。新しいショッピングモールが春に駅の近くにできるそうだ。", tip: "appear（見える）→apparent（見える）。『見たところ』と覚える。", scene: "放課後、友だちが『駅前にショッピングモールができるらしいよ』と耳打ちする。", flow: ["見たところ", "どうやら～らしい"], fam: ["apparent（明らかな・見かけの）", "appear（現れる）"], pair: "clearly は「はっきり」、apparently は「聞いた話では・どうやら」。" },
    "consequently": { hint: "sequ は『あとに続く』", core: "前のことに『続いて起こったこと』を言う。まったく勉強しなかった→だから落ちた。", tip: "consequence（結果）＋ly。so や therefore と同じはたらき。", scene: "テスト前に一ページも開かなかったノート。返ってきた答案は赤いバツだらけ。", flow: ["あとに続いて", "その結果"], fam: ["consequence（結果）"], pair: "therefore と同じ「だから」。consequently は結果に重点がある。" },
    "increasingly": { hint: "数や人気が上へ上へ、と変わっていく", core: "『どんどん増えていくように』。ネットショッピングが、どの年代でもどんどん人気に。", tip: "increase（増える）から。more and more と同じ感じ。", pic: "📈", scene: "駅前の宅配ボックスが、月を追うごとに一つ、また一つと増えていく。", flow: ["増えていくように", "ますます"], fam: ["increase（増える）"], pair: "more and more とほぼ同じ。increasingly は形容詞の前に置く。" }
  }
});
